### Question 5: Lock-Free Queue with Fixed Capacity

Implement a lock-free circular buffer queue with fixed capacity N that supports
multiple producers and multiple consumers. Use compare-and-swap for all
operations.

```c
template<typename T, size_t N>
class LockFreeQueue {
    // Your implementation here
};
```

answer:
```c
#include <atomic>
#include <memory>

template<typename T, size_t N>
class LockFreeQueue {
    static_assert((N & (N - 1)) == 0, "N must be power of 2");

    struct Node {
        std::atomic<bool> ready{false};
        T data;
    };

    Node* buffer;
    const size_t mask;
    alignas(64) std::atomic<size_t> head;  // Cache-line padded
    alignas(64) std::atomic<size_t> tail;

public:
    explicit LockFreeQueue() : buffer(new Node[N]), mask(N - 1) {
        head.store(0, std::memory_order_relaxed);
        tail.store(0, std::memory_order_relaxed);
    }

    ~LockFreeQueue() { delete[] buffer; }

    bool enqueue(const T& value) {
        size_t tail_idx = tail.load(std::memory_order_relaxed);
        size_t head_idx = head.load(std::memory_order_acquire);

        // Full check
        if (((tail_idx - head_idx) & mask) == mask) {
            return false;  // Queue full
        }

        Node* node = &buffer[tail_idx & mask];

        // Claim this slot
        if (!tail.compare_exchange_weak(tail_idx, tail_idx + 1,
                                        std::memory_order_relaxed,
                                        std::memory_order_relaxed)) {
            return false;  // CAS failed, try again
        }

        // Write data and mark ready
        node->data = value;
        node->ready.store(true, std::memory_order_release);
        return true;
    }

    bool dequeue(T& result) {
        size_t head_idx = head.load(std::memory_order_relaxed);
        size_t tail_idx = tail.load(std::memory_order_acquire);

        // Empty check
        if (((tail_idx - head_idx) & mask) == 0) {
            return false;  // Queue empty
        }

        Node* node = &buffer[head_idx & mask];

        // Wait for data to be ready
        while (!node->ready.load(std::memory_order_acquire)) {
            // Could add pause/yield here
        }

        result = node->data;
        node->ready.store(false, std::memory_order_relaxed);

        // Advance head
        head.compare_exchange_strong(head_idx, head_idx + 1,
                                     std::memory_order_release,
                                     std::memory_order_relaxed);
        return true;
    }

    // Bonus: blocking variants using semaphores or condition variables
};
```

