### Question 6: Synchronization for Producer-Consumer Pipeline

Design a synchronization scheme for a 3-stage producer-consumer pipeline where:
- Stage 0 produces items
- Stage 1 processes items from Stage 0
- Stage 2 processes items from Stage 1
- Each stage runs in its own thread
- Items flow through all stages in order

answer:
```c
#include <semaphore.h>
#include <queue>
#include <mutex>
#include <condition_variable>

template<typename T>
class Pipeline {
    struct Stage {
        std::queue<T> queue;
        std::mutex mtx;
        std::condition_variable cv;
        std::counting_semaphore<100> items{0};  // Or semaphore
        std::binary_semaphore ready{0};
    };

    Stage s0, s1, s2;
    std::atomic<bool> running{true};

public:
    void producer() {
        int i = 0;
        while (running) {
            T item = produce(i++);

            {
                std::lock_guard<std::mutex> lk(s0.mtx);
                s0.queue.push(std::move(item));
            }
            s0.cv.notify_one();

            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
        // Signal end
        s0.cv.notify_all();
    }

    void stage1_worker() {
        while (true) {
            T item;
            {
                std::unique_lock<std::mutex> lk(s0.mtx);
                s0.cv.wait(lk, [&] { 
                    return !s0.queue.empty() || !running.load(); 
                });
                if (s0.queue.empty()) break;
                item = std::move(s0.queue.front());
                s0.queue.pop();
            }

            process1(item);

            {
                std::lock_guard<std::mutex> lk(s1.mtx);
                s1.queue.push(std::move(item));
            }
            s1.cv.notify_one();
        }
        s1.cv.notify_all();
    }

    void stage2_worker() {
        while (true) {
            T item;
            {
                std::unique_lock<std::mutex> lk(s1.mtx);
                s1.cv.wait(lk, [&] { 
                    return !s1.queue.empty(); 
                });
                if (s1.queue.empty()) break;
                item = std::move(s1.queue.front());
                s1.queue.pop();
            }

            process2(item);

            {
                std::lock_guard<std::mutex> lk(s2.mtx);
                s2.queue.push(std::move(item));
            }
            s2.cv.notify_one();
        }
    }

    void run() {
        std::thread t0([this] { producer(); });
        std::thread t1([this] { stage1_worker(); });
        std::thread t2([this] { stage2_worker(); });

        std::this_thread::sleep_for(std::chrono::seconds(5));
        running = false;

        t0.join();
        t1.join();
        t2.join();
    }

    virtual T produce(int i) = 0;
    virtual void process1(T&) = 0;
    virtual void process2(T&) = 0;
};
