### Question 7: Read-Copy-Update (RCU) Implementation

Explain RCU (Read-Copy-Update) synchronization and implement a simplified version
for a linked list with multiple readers and occasional updates.

answer:
```c
#include <atomic>
#include <thread>
#include <vector>

// Simplified RCU implementation
class RCUList {
    struct Node {
        int data;
        std::atomic<Node*> next;
        std::atomic<int> refcount;
        std::atomic<bool> deleted{false};
    };

    std::atomic<Node*> head;
    std::atomic<std::thread::id> writer_id;

public:
    // Reader: increment refcount, read, decrement refcount
    int find(int key) {
        Node* curr = head.load(std::memory_order_acquire);
        while (curr) {
            curr->refcount.fetch_add(1, std::memory_order_acq_rel);

            if (curr->deleted.load(std::memory_order_acquire)) {
                curr->refcount.fetch_sub(1, std::memory_order_acq_rel);
                curr = curr->next.load(std::memory_order_acquire);
                continue;
            }

            if (curr->data == key) {
                curr->refcount.fetch_sub(1, std::memory_order_acq_rel);
                return key;
            }

            Node* next = curr->next.load(std::memory_order_acquire);
            curr->refcount.fetch_sub(1, std::memory_order_acq_rel);
            curr = next;
        }
        return -1;
    }

    // Writer: mark deleted, wait for readers, then free
    bool remove(int key) {
        // Find and mark
        Node* prev = nullptr;
        Node* curr = head.load();

        while (curr && curr->data != key) {
            prev = curr;
            curr = curr->next.load();
        }

        if (!curr) return false;

        // Mark as deleted (new readers will skip)
        curr->deleted.store(true, std::memory_order_release);

        // Wait for existing readers to finish (simplified - real RCU uses grace periods)
        while (curr->refcount.load(std::memory_order_acquire) > 0) {
            std::this_thread::yield();
        }

        // Unlink
        if (prev) {
            prev->next.store(curr->next.load(), std::memory_order_release);
        } else {
            head.store(curr->next.load(), std::memory_order_release);
        }

        delete curr;
        return true;
    }

    void insert(int key) {
        Node* new_node = new Node{key, nullptr, 0, false};
        new_node->next.store(head.load(std::memory_order_acquire));
        head.store(new_node, std::memory_order_release);
    }
};

// Real RCU uses:
// - Quiescent states (points where no RCU read-side critical sections)
// - Grace periods (time for all pre-existing readers to pass a quiescent state)
// - Callback queues for deferred frees
// - Lightweight readers (no atomic operations in best case)
