### Question 8: Thread-Safe Object Pool

Implement a thread-safe object pool using a lock-free stack for available
objects. Include methods to acquire and release objects, with optional cleanup
when the pool is destroyed.

```c
template<typename T>
class ObjectPool {
    // Implementation
};
```

answer:
```c
#include <atomic>
#include <memory>
#include <vector>
#include <functional>

template<typename T>
class ObjectPool {
    struct Slot {
        T object;
        std::atomic<Slot*> next;
        std::atomic<bool> in_use;

        Slot() : next(nullptr), in_use(false) {}
    };

    std::atomic<Slot*> free_stack;
    std::vector<std::unique_ptr<Slot>> slots;
    const size_t max_size;
    std::atomic<size_t> active_count{0};

    // For cleanup
    std::atomic<bool> destroyed{false};

public:
    explicit ObjectPool(size_t max) : max_size(max) {
        slots.reserve(max);
        for (size_t i = 0; i < max; ++i) {
            auto slot = std::make_unique<Slot>();
            slot->next.store(free_stack.load(std::memory_order_relaxed));
            free_stack.store(slot.get());
            slots.push_back(std::move(slot));
        }
    }

    ~ObjectPool() {
        destroyed.store(true, std::memory_order_seq_cst);
        // Wait for all releases to complete
        while (active_count.load(std::memory_order_acquire) > 0) {
            std::this_thread::yield();
        }
    }

    T* acquire() {
        if (destroyed.load(std::memory_order_acquire)) {
            return nullptr;
        }

        Slot* slot = free_stack.load(std::memory_order_acquire);

        while (slot) {
            Slot* next = slot->next.load(std::memory_order_acquire);

            if (free_stack.compare_exchange_weak(slot, next,
                                                  std::memory_order_acq_rel,
                                                  std::memory_order_acquire)) {
                // Successfully claimed
                if (slot->in_use.exchange(true, std::memory_order_acquire)) {
                    // Already in use (unlikely with lock-free)
                    continue;
                }
                active_count.fetch_add(1, std::memory_order_acq_rel);
                return &slot->object;
            }
            // slot updated by CAS failure
        }

        return nullptr;  // Pool exhausted
    }

    void release(T* obj) {
        if (!obj) return;

        // Find slot from object pointer
        Slot* slot = reinterpret_cast<Slot*>(obj);

        // Reset object state (call destructor then placement new)
        obj->~T();
        new (obj) T();

        slot->in_use.store(false, std::memory_order_release);
        slot->next.store(free_stack.load(std::memory_order_relaxed));

        while (!free_stack.compare_exchange_weak(slot->next, slot,
                                                  std::memory_order_acq_rel,
                                                  std::memory_order_acquire)) {
            // Continue trying
        }

        active_count.fetch_sub(1, std::memory_order_acq_rel);
    }

    size_t available() const {
        size_t count = 0;
        Slot* curr = free_stack.load(std::memory_order_acquire);
        while (curr) {
            ++count;
            curr = curr->next.load(std::memory_order_acquire);
        }
        return count;
    }
};
```

