### Question 10: Dining Philosophers with Different Synchronization

Implement the Dining Philosophers problem using two different synchronization
mechanisms:
1. Monitor-based solution
2. Lock-free solution using compare-and-swap

answer:
```c
// SOLUTION 1: Monitor-Based (using mutex + condition variables)

#include <mutex>
#include <condition_variable>

class DiningPhilosophersMonitor {
    enum State { THINKING, HUNGRY, EATING };
    std::array<State, 5> state;
    std::array<std::condition_variable, 5> self;
    std::mutex mtx;

    int left(int i) { return (i + 4) % 5; }
    int right(int i) { return (i + 1) % 5; }

    bool test(int i) {
        return state[left(i)] != EATING &&
               state[right(i)] != EATING &&
               state[i] == HUNGRY;
    }

public:
    DiningPhilosophersMonitor() {
        state.fill(THINKING);
    }

    void pickup(int i) {
        std::unique_lock<std::mutex> lock(mtx);
        state[i] = HUNGRY;
        // Wait until both forks available
        self[i].wait(lock, [this, i] { return test(i); });
        state[i] = EATING;
    }

    void putdown(int i) {
        std::unique_lock<std::mutex> lock(mtx);
        state[i] = THINKING;
        // Signal neighbors they might be able to eat
        self[left(i)].notify_one();
        self[right(i)].notify_one();
    }
};

// SOLUTION 2: Lock-Free (using CAS)

#include <atomic>

class DiningPhilosophersLockFree {
    // Each fork is represented by a philosopher number or -1 if free
    // Forks are numbered 0-4, fork i is between philosopher i and (i+1)%5
    std::array<std::atomic<int>, 5> forks;

    // Per-philosopher state
    std::array<std::atomic<bool>, 5> wants_to_eat;
    std::array<std::atomic<int>, 5> eat_count;

public:
    DiningPhilosophersLockFree() {
        for (int i = 0; i < 5; ++i) {
            forks[i].store(i, std::memory_order_relaxed);  // Initially owned
            wants_to_eat[i].store(false);
            eat_count[i].store(0);
        }
    }

    bool try_acquire_forks(int i) {
        int left_fork = i;
        int right_fork = (i + 1) % 5;

        // Try to claim left fork
        int expected = i;
        if (!forks[left_fork].compare_exchange_weak(expected, -1,
                std::memory_order_acq_rel, std::memory_order_relaxed)) {
            return false;  // Left fork taken
        }

        // Try to claim right fork
        expected = (i + 1) % 5;
        if (!forks[right_fork].compare_exchange_weak(expected, -1,
                std::memory_order_acq_rel, std::memory_order_relaxed)) {
            // Failed to get right fork, release left
            forks[left_fork].store(i, std::memory_order_release);
            return false;
        }

        return true;
    }

    void release_forks(int i) {
        int left_fork = i;
        int right_fork = (i + 1) % 5;

        forks[left_fork].store((i + 4) % 5, std::memory_order_release);
        forks[right_fork].store(i, std::memory_order_release);
    }

    void dine(int i) {
        // Think
        std::this_thread::sleep_for(std::chrono::milliseconds(100));

        wants_to_eat[i].store(true, std::memory_order_release);

        // Try to acquire forks with exponential backoff
        int backoff = 1;
        while (!try_acquire_forks(i)) {
            // Backoff
            std::this_thread::sleep_for(std::chrono::microseconds(backoff));
            backoff = std::min(backoff * 2, 1000);
        }

        // Eat
        eat_count[i].fetch_add(1, std::memory_order_relaxed);
        std::this_thread::sleep_for(std::chrono::milliseconds(50));

        release_forks(i);
        wants_to_eat[i].store(false, std::memory_order_release);
    }
};

// Usage for both solutions:
void run_simulation() {
    DiningPhilosophersMonitor dm;
    std::vector<std::thread> threads;

    for (int i = 0; i < 5; ++i) {
        threads.emplace_back([&dm, i] {
            for (int j = 0; j < 10; ++j) {
                dm.pickup(i);
                // Eating happens here
                dm.putdown(i);
            }
        });
    }

    for (auto& t : threads) t.join();
}
```

