### Question 11: Sequence Lock (SeqLock) Implementation

Implement a sequence lock for readers that never block and writers that never
starve. Explain when this is appropriate to use.

answer:
```c
#include <atomic>
#include <cstdint>

template<typename T>
class SeqLock {
    mutable std::atomic<uint64_t> sequence{0};
    T data;

public:
    // Writer: increment sequence, update data, increment sequence
    void write(const T& new_data) {
        uint64_t seq = sequence.load(std::memory_order_relaxed);

        // Write phase 1: increment sequence (odd = writing)
        sequence.store(seq + 1, std::memory_order_release);

        // Write data
        data = new_data;

        // Write phase 2: increment sequence (even = not writing)
        sequence.store(seq + 2, std::memory_order_release);
    }

    // Reader: retry until sequence is even and unchanged
    T read() const {
        T local_data;
        uint64_t seq;

        do {
            seq = sequence.load(std::memory_order_acquire);

            // Check if writer is active (odd sequence)
            if (seq & 1) {
                std::this_thread::yield();
                continue;
            }

            // Read data
            local_data = data;

            // Memory barrier before re-reading sequence
            std::atomic_thread_fence(std::memory_order_acquire);

        } while (seq != sequence.load(std::memory_order_acquire));

        return local_data;
    }

    // Try-read: returns false if concurrent write detected
    bool try_read(T& result) const {
        uint64_t seq = sequence.load(std::memory_order_acquire);

        if (seq & 1) return false;  // Writer active

        result = data;

        std::atomic_thread_fence(std::memory_order_acquire);

        return seq == sequence.load(std::memory_order_acquire);
    }
};

// Use case: frequently read, rarely written data
// Examples: system clock, configuration, statistics
// NOT suitable for: frequently written data, data requiring strong consistency

class SystemStats {
    SeqLock<uint64_t> total_requests;
    SeqLock<uint64_t> total_errors;
    SeqLock<std::vector<int>> recent_latencies;

public:
    void record_request(uint64_t latency, bool success) {
        // Writers don't block
        total_requests.write(total_requests.read() + 1);
        if (!success) {
            total_errors.write(total_errors.read() + 1);
        }
    }

    // Readers never block, may retry
    uint64_t get_total_requests() const {
        return total_requests.read();
    }

    double get_error_rate() const {
        uint64_t total = total_requests.read();
        uint64_t errors = total_errors.read();
        return total > 0 ? static_cast<double>(errors) / total : 0.0;
    }
};
```

