### Question 12: Thread-Safe Singleton with Double-Checked Locking

Explain the double-checked locking pattern for singletons and implement it
correctly. Discuss why naive implementations fail.

answer:
```c
#include <atomic>
#include <mutex>

// PROBLEM: Naive implementation (BROKEN)

class BrokenSingleton {
    static BrokenSingleton* instance;
    static std::mutex mtx;

public:
    static BrokenSingleton* get_instance() {
        if (instance == nullptr) {  // First check (no lock)
            std::lock_guard<std::mutex> lock(mtx);
            if (instance == nullptr) {  // Second check (with lock)
                instance = new BrokenSingleton();
            }
        }
        return instance;
    }
};

// Why broken on some platforms:
// 1. Compiler might reorder: instance = new Singleton()
//    into: instance = malloc(); construct(instance);
//    Another thread might see non-null pointer to unconstructed object
// 3. Hardware might have weak memory ordering

// SOLUTION 1: C++11 and later (with memory_order)

class SingletonV1 {
    static std::atomic<SingletonV1*> instance;
    static std::mutex mtx;

public:
    static SingletonV1* get_instance() {
        SingletonV1* tmp = instance.load(std::memory_order_acquire);
        if (tmp == nullptr) {
            std::lock_guard<std::mutex> lock(mtx);
            tmp = instance.load(std::memory_order_relaxed);
            if (tmp == nullptr) {
                tmp = new SingletonV1();
                instance.store(tmp, std::memory_order_release);
            }
        }
        return tmp;
    }
};

// SOLUTION 2: Magic statics (simplest, C++11 and later)

class SingletonV2 {
public:
    static SingletonV2& get_instance() {
        // Thread-safe, guaranteed to be initialized once
        static SingletonV2 instance;
        return instance;
    }
};

// SOLUTION 3: Call once (explicit)

class SingletonV3 {
    static std::once_flag flag;
    static SingletonV3* instance;

    SingletonV3() = default;

public:
    static SingletonV3* get_instance() {
        std::call_once(flag, []() {
            instance = new SingletonV3();
        });
        return instance;
    }
};

// SOLUTION 4: Meyer's Singleton (simplest, recommended)

class SingletonV4 {
    SingletonV4() = default;
    SingletonV4(const SingletonV4&) = delete;
    SingletonV4& operator=(const SingletonV4&) = delete;

public:
    static SingletonV4& get_instance() {
        static SingletonV4 instance;
        return instance;
    }
};

// Comparison:
// - Magic statics / Meyer's: Simplest, no locks, C++11 guarantees
// - call_once: Explicit, good when initialization is complex
// - DCLP with atomic: Works but complex, avoid unless necessary
