public:
    // Push with notification
    void push(T value) {
        {
            std::lock_guard<std::mutex> lock(mtx);
            queue.push(std::move(value));
        }
        cv.notify_one();  // Wake one consumer
    }

    // Pop with spurious wakeup handling
    std::optional<T> pop() {
        std::unique_lock<std::mutex> lock(mtx);

        // SPURIOUS WAKEUP HANDLING:
        // Condition variable wait can return without notify being called.
        // Must use a predicate loop, not just a simple wait.

        // Wait until queue not empty OR closed
        cv.wait(lock, [this]() {
            return !queue.empty() || closed;
        });

        if (queue.empty()) {
            return std::nullopt;  // Closed
        }

        T value = std::move(queue.front());
        queue.pop();
        return value;
    }

    // Pop with timeout
    std::optional<T> pop_for(std::chrono::milliseconds timeout) {
        std::unique_lock<std::mutex> lock(mtx);

        // cv.wait_for returns false if timeout expires
        // even if predicate is still false
        if (!cv.wait_for(lock, timeout, [this]() {
            return !queue.empty() || closed;
        })) {
            return std::nullopt;  // Timeout
        }

        if (queue.empty()) {
            return std::nullopt;  // Closed
        }

        T value = std::move(queue.front());
        queue.pop();
        return value;
    }

    void close() {
        {
            std::lock_guard<std::mutex> lock(mtx);
            closed = true;
        }
        cv.notify_all();  // Wake all consumers
    }
};

// WRONG implementations that don't handle spurious wakeups:

// WRONG 1: No predicate
void wrong_pop_1() {
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock);  // WRONG! May wake without queue having data
    // ...
}

void wrong_pop_2() {
    std::unique_lock<std::mutex> lock(mtx);
    if (cv.wait(lock, [this]() { return !queue.empty(); })) {
        // WRONG! Spurious wakeup could make this true when queue empty
        // ...
    }
}

// WRONG 3: Checking condition after wait
void wrong_pop_3() {
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock);
    if (!queue.empty()) {  // WRONG! Race condition
        // ...
    }
}

// CORRECT pattern:
void correct_pop() {
    std::unique_lock<std::mutex> lock(mtx);
    cv.wait(lock, [this]() { return !queue.empty(); });
    // Now we know queue is not empty
}

// Why spurious wakeups exist:
// 1. Implementation efficiency on some platforms
// 2. Avoiding "lost wakeup" problems
// 3. OS-level timing issues with pthread condition variables
