### Question 14: Futex-Based Synchronization

Implement a basic mutex using futex (fast userspace mutex) system calls.
Explain the advantages of futex over traditional futex operations.

answer:
```c
// Note: This is a simplified educational implementation
// Real implementations are more complex

#include <atomic>
#include <linux/futex.h>
#include <sys/syscall.h>
#include <unistd.h>
#include <cerrno>

class FutexMutex {
    std::atomic<int> state{0};
    static constexpr int FREE = 0;
    static constexpr int LOCKED = 1;
    static constexpr int CONTENDED = 2;

    static long futex_wait(std::atomic<int>* addr, int val, 
                           const timespec* timeout = nullptr) {
        return syscall(SYS_futex, addr, FUTEX_WAIT, val, timeout, nullptr, 0);
    }

    static long futex_wake(int* addr, int val) {
        return syscall(SYS_futex, addr, FUTEX_WAKE, val, nullptr, nullptr, 0);
    }

public:
    void lock() {
        // Try to acquire lock in userspace
        int expected = FREE;
        if (state.compare_exchange_weak(expected, LOCKED,
                                        std::memory_order_acquire,
                                        std::memory_order_relaxed)) {
            return;  // Got lock immediately
        }

        // Lock is held, need to wait
        if (expected != CONTENDED) {
            // Upgrade to contended state
            expected = LOCKED;
            state.compare_exchange_strong(expected, CONTENDED,
                                          std::memory_order_relaxed,
                                          std::memory_order_relaxed);
        }

        // Wait on the futex
        while (true) {
            // Sleep until state might change
            futex_wait(&state, CONTENDED);

            int current = state.load(std::memory_order_acquire);
            if (current == CONTENDED) {
                continue;  // Still contended, keep waiting
            }

            // Try to acquire
            expected = FREE;
            if (state.compare_exchange_weak(expected, LOCKED,
                                            std::memory_order_acquire,
                                            std::memory_order_relaxed)) {
                return;  // Got lock
            }
            // Otherwise, state was changed by waker, try again
        }
    }

    void unlock() {
        int current = state.load(std::memory_order_relaxed);
        state.store(FREE, std::memory_order_release);

        if (current == CONTENDED) {
            // There are waiters, wake one
            futex_wake(&state, 1);
        }
    }
};

// Advantages of futex:
// 1. No kernel transition when lock is uncontended (fast path)
// 2. Only kernel call when contention occurs (slow path)
// 3. Combines efficiency of userspace sync with kernel support for contention
// 4. Scalable: only wake specific waiters, not broadcast

// Futex operations:
// - FUTEX_WAIT: Block if value matches (with optional timeout)
// - FUTEX_WAKE: Wake N waiters
// - FUTEX_REQUEUE: Move waiters to different futex (for broadcast)
// - FUTEX_CMP_REQUEUE: Conditional requeue

// Linux kernel futex guarantees:
// - Waiters are woken in FIFO order
// - No lost wakeups
// - Memory ordering preserved
