// Software Transactional Memory (STM) Implementation

template<typename T>
class TMVar {
    T value;
    int tid;  // Transaction ID that last modified

public:
    TMVar(T initial = T{}) : value(initial), tid(-1) {}

    T read() const { return value; }
    void write(T v) { value = v; }
    int get_tid() const { return tid; }
    void set_tid(int t) { tid = t; }
};

struct TransactionLog {
    int tid;
    std::vector<std::pair<void*, void*>> writes;  // (address, old_value)
    std::vector<std::pair<void*, void*>> reads;   // (address, read_value)
    bool committed = false;
};

class STM {
    static std::atomic<int> global_tid;
    static thread_local int local_tid;
    static thread_local std::unique_ptr<TransactionLog> log;

public:
    static void begin() {
        if (!log) {
            log = std::make_unique<TransactionLog>();
            log->tid = global_tid.fetch_add(1);
        }
    }

    static bool commit() {
        if (!log) return true;

        // Validate all reads
        for (auto& [addr, read_val] : log->reads) {
            // Check if value changed since read
            // (simplified - real STM uses version numbers)
        }

        // Apply writes atomically
        for (auto& [addr, old_val] : log->writes) {
            // Restore old value on rollback
        }

        log->committed = true;
        log.reset();
        return true;
    }

    static void abort() {
        // Rollback all writes
        for (auto& [addr, old_val] : log->writes) {
            // Restore old values
        }
        log.reset();
    }

    template<typename T>
    static T read(TMVar<T>& var) {
        T val = var.read();
        if (log) {
            log->reads.push_back({&var, &val});
        }
        return val;
    }

    template<typename T>
    static void write(TMVar<T>& var, T val) {
        if (log) {
            log->writes.push_back({&var, &var.read()});
        }
        var.write(val);
    }

    template<typename F>
    static auto atomic(F&& func) -> decltype(func()) {
        while (true) {
            begin();
            try {
                auto result = func();
                if (commit()) {
                    return result;
                }
            } catch (...) {
                abort();
                throw;
            }
            abort();
            // Exponential backoff before retry
        }
    }
};

// Usage example:
TMVar<int> account1{100};
TMVar<int> account2{100};

void transfer(int amount) {
    STM::atomic([&]() {
        int bal1 = STM::read(account1);
        int bal2 = STM::read(account2);

        if (bal1 >= amount) {
            STM::write(account1, bal1 - amount);
            STM::write(account2, bal2 + amount);
        }
    });
}

// Hardware Transactional Memory (HTM):
// - Intel TSX (Transactional Synchronization Extensions)
// - IBM Power8+ HTM
// - Limited transaction sizes, aborts on various events
// - Fallback to software locks needed

// Advantages of STM/HTM over locks:
// - Composability (can combine transactions)
// - No deadlock
// - No lock convoy
// - Easier reasoning about correctness

// Disadvantages:
// - Overhead (STM) or limitations (HTM)
// - Starvation possible under high contention
// - Cannot handle I/O or system calls in transaction
