### Question 16: Priority Inversion Problem

Explain the priority inversion problem and implement a solution using priority
inheritance. Include a scenario demonstrating the problem.

answer:
```c
#include <atomic>
#include <thread>
#include <vector>
#include <queue>
#include <memory>

// PRIORITY INVERSION PROBLEM:
// High priority task H waits for lock held by Low priority task L
// Medium priority task M preempts L, delaying H
// Solution: M temporarily inherits H's priority while holding the lock

class PriorityInheritanceMutex {
    enum class State { FREE, HELD };

    struct WaitingTask {
        int priority;
        std::condition_variable* cv;
        bool ready = false;
    };

    std::atomic<State> state{State::FREE};
    int owner_tid = -1;
    int owner_priority = 0;
    std::mutex mtx;
    std::queue<WaitingTask*> wait_queue;

public:
    void lock(int priority) {
        std::unique_lock<std::mutex> lock(mtx);

        WaitingTask wait{priority, nullptr};
        std::condition_variable cv;
        wait.cv = &cv;

        while (true) {
            State current = state.load(std::memory_order_acquire);

            if (current == State::FREE) {
                // Try to acquire
                if (state.compare_exchange_weak(current, State::HELD,
                        std::memory_order_acq_rel, std::memory_order_relaxed)) {
                    owner_tid = std::this_thread::get_id().hash();
                    owner_priority = priority;
                    return;
                }
            } else {
                // Check if we should boost owner's priority
                if (priority > owner_priority) {
                    owner_priority = priority;
                    // In real implementation, would call OS to boost thread priority
                }

                // Wait
                wait_queue.push(&wait);
                cv.wait(lock, [&]() { return wait.ready; });
                wait_queue.pop();
            }
        }
    }

    void unlock() {
        std::unique_lock<std::mutex> lock(mtx);

        // Find next waiter with highest priority
        int max_priority = 0;
        WaitingTask* next = nullptr;

        std::queue<WaitingTask*> new_queue;
        while (!wait_queue.empty()) {
            auto* task = wait_queue.front();
            wait_queue.pop();
            if (!next || task->priority > max_priority) {
                max_priority = task->priority;
                next = task;
            }
            new_queue.push(task);
        }
        wait_queue = std::move(new_queue);

        if (next) {
            next->ready = true;
            next->cv->notify_one();
        } else {
            state.store(State::FREE, std::memory_order_release);
            owner_priority = 0;
        }
    }
};

// DEMONSTRATION:

PriorityInheritanceMutex resource_mutex;
std::atomic<int> completion_order{0};

void low_priority_task() {
    resource_mutex.lock(10);  // Low priority (10)
    std::this_thread::sleep_for(std::chrono::milliseconds(100));
    resource_mutex.unlock();
    completion_order.fetch_add(1);
}

void medium_priority_task() {
    std::this_thread::sleep_for(std::chrono::milliseconds(10));
    // Will preempt low priority task
    std::this_thread::sleep_for(std::chrono::milliseconds(200));
    completion_order.fetch_add(2);
}

void high_priority_task() {
    std::this_thread::sleep_for(std::chrono::milliseconds(20));
    resource_mutex.lock(50);  // High priority (50)
    resource_mutex.unlock();
    completion_order.fetch_add(3);
}

void demonstrate_priority_inversion() {
    // WITHOUT priority inheritance:
    // 1. Low (10) acquires lock
    // 2. Medium (30) preempts Low
    // 3. High (50) tries to lock, waits for Low
    // 4. High blocked by Medium (priority inversion!)
    // 5. Low can't run to release lock

    // WITH priority inheritance:
    // 1. Low (10) acquires lock
    // 2. Medium (30) preempts Low
    // 3. High (50) tries to lock
    // 4. Low's priority boosted to 50
    // 5. Low preempts Medium, runs, releases lock
    // 6. High acquires lock, completes
}

// Real-world example: Mars Pathfinder rover
// - High priority: meteorological data processing
// - Medium priority: bus management
// - Low priority: occasional bus arbitration
// - Solved by adding priority inheritance to vxWorks mutex
```

