template<typename T>
class ConcurrentList {
    struct Node {
        T data;
        Node* next;
        mutable std::mutex mtx;

        Node(const T& v) : data(v), next(nullptr) {}
    };

    Node* head;
    std::mutex head_mtx;  // Protects head pointer itself

public:
    ConcurrentList() : head(nullptr) {}

    ~ConcurrentList() {
        std::lock_guard<std::mutex> lock(head_mtx);
        while (head) {
            Node* next = head->next;
            delete head;
            head = next;
        }
    }

    // Fine-grained insert at head
    void insert(const T& value) {
        Node* new_node = new Node(value);

        std::lock_guard<std::mutex> lock(head_mtx);
        new_node->next = head;
        head = new_node;
    }

    // Fine-grained search with hand-over-hand locking
    bool find(const T& value) const {
        std::mutex* prev_mtx = &head_mtx;
        std::lock_guard<std::mutex> lock(*prev_mtx);

        Node* curr = head;
        while (curr) {
            // Lock current node
            std::lock_guard<std::mutex> curr_lock(curr->mtx);

            // Release previous lock (hand-over-hand)
            prev_mtx->unlock();

            if (curr->data == value) {
                return true;
            }

            Node* next = curr->next;
            if (next) {
                prev_mtx = &next->mtx;
                prev_mtx->lock();
            }

            curr = next;
        }

        return false;
    }

    // Fine-grained erase
    bool erase(const T& value) {
        std::lock_guard<std::mutex> head_lock(head_mtx);

        if (!head) return false;

        // Lock first node
        std::lock_guard<std::mutex> curr_lock(head->mtx);

        if (head->data == value) {
            Node* to_delete = head;
            head = head->next;
            curr_lock.unlock();
            head_lock.unlock();
            delete to_delete;
            return true;
        }

        Node* curr = head;
        while (curr->next) {
            Node* next = curr->next;
            std::lock_guard<std::mutex> next_lock(next->mtx);

            if (next->data == value) {
                curr->next = next->next;
                next_lock.unlock();
                delete next;
                return true;
            }

            // Move to next
            curr = next;
        }

        return false;
    }

    // Range query with minimal locking
    template<typename F>
    void for_each(F&& func) {
        std::vector<std::unique_lock<std::mutex>> locks;

        std::lock_guard<std::mutex> lock(head_mtx);
        Node* curr = head;

        while (curr) {
            locks.push_back(std::unique_lock<std::mutex>(curr->mtx, std::try_to_lock_t{}));
            if (locks.back().owns_lock()) {
                func(curr->data);
                curr = curr->next;
            } else {
                // Skip locked node
                curr = curr->next;
            }
        }
    }
};

// Optimizations:
// 1. Use std::shared_mutex for readers (read-write lock per node)
// 2. Use lock striping (group nodes, one lock per group)
// 3. Use RCU for read-heavy workloads
// 4. Use skip lists for O(log n) operations

