### Question 19: Semaphore Implementation and Analysis

Implement counting semaphores using mutex and condition variable, then compare
with atomic-based implementation. Analyze performance trade-offs.

answer:
```c
#include <mutex>
#include <condition_variable>

// Counting Semaphore using Mutex + Condition Variable

class Semaphore {
    std::mutex mtx;
    std::condition_variable cv;
    int count;
    int waiters;

public:
    explicit Semaphore(int initial_count) 
        : count(initial_count), waiters(0) {}

    void wait() {
        std::unique_lock<std::mutex> lock(mtx);
        ++waiters;

        cv.wait(lock, [this]() {
            return count > 0;
        });

        --waiters;
        --count;
    }

    bool try_wait() {
        std::lock_guard<std::mutex> lock(mtx);
        if (count > 0) {
            --count;
            return true;
        }
        return false;
    }

    bool try_wait_for(std::chrono::milliseconds timeout) {
        std::unique_lock<std::mutex> lock(mtx);
        ++waiters;

        bool acquired = cv.wait_for(lock, timeout, [this]() {
            return count > 0;
        });

        --waiters;
        if (acquired) {
            --count;
            return true;
        }
        return false;
    }

    void signal() {
        std::lock_guard<std::mutex> lock(mtx);
        ++count;
        if (waiters > 0) {
            cv.notify_one();
        }
    }

    void signal_all() {
        std::lock_guard<std::mutex> lock(mtx);
        ++count;
        cv.notify_all();
    }
};

// Atomic-based semaphore (lock-free for fast path)

class AtomicSemaphore {
    std::atomic<int> count;
    static constexpr int WAITING = -1;

public:
    explicit AtomicSemaphore(int initial) : count(initial) {}

    void wait() {
        int c = count.fetch_sub(1, std::memory_order_acquire);

        if (c <= 0) {
            // Need to wait - use futex or spin
            // Simplified: spin wait
            while (count.load(std::memory_order_acquire) <= 0) {
                std::this_thread::yield();
            }
        }
    }

    bool try_wait() {
        int c = count.load(std::memory_order_acquire);
        while (c > 0) {
            if (count.compare_exchange_weak(c, c - 1,
                    std::memory_order_acq_rel, std::memory_order_acquire)) {
                return true;
            }
        }
        return false;
    }

    void signal() {
        count.fetch_add(1, std::memory_order_release);
    }
};

