```

answer:
```c
#include <atomic>
#include <mutex>
#include <condition_variable>

// Sense-reversing barrier (efficient for repeated use)

class Barrier {
    const int num_threads;
    std::atomic<int> count{0};
    std::atomic<int> generation{0};
    std::atomic<int> sense{0};
    std::mutex mtx;
    std::condition_variable cv;

public:
    explicit Barrier(int n) : num_threads(n) {}

    void wait() {
        int local_sense = sense.load(std::memory_order_acquire);

        int prev = count.fetch_add(1, std::memory_order_acq_rel);

        if (prev == num_threads - 1) {
            // Last thread: reset for next use
            count.store(0, std::memory_order_release);
            sense.store(!local_sense, std::memory_order_release);
            cv.notify_all();
        } else {
            // Wait for other threads
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this, local_sense]() {
                return sense.load(std::memory_order_acquire) != local_sense;
            });
        }
    }
};

// Tournament barrier (tree-based, O(log N) wakeup)

class TournamentBarrier {
    struct Node {
        std::atomic<bool> flag{false};
        std::mutex mtx;
        std::condition_variable cv;
    };

    const int num_threads;
    const int num_levels;
    std::vector<Node> nodes;
    std::atomic<int> sense{0};

public:
    explicit TournamentBarrier(int n) : num_threads(n) {
        num_levels = 0;
        int temp = n;
        while (temp > 1) {
            temp = (temp + 1) / 2;
            ++num_levels;
        }
        nodes.resize(num_threads);
    }

    void wait() {
        int local_sense = sense.load(std::memory_order_acquire);
        int my_id = std::this_thread::get_id() % num_threads;  // Simplified

        // Arrival phase: walk up the tree
        for (int level = 0; level < num_levels; ++level) {
            int partner = my_id ^ (1 << level);
            if (partner < num_threads) {
                Node& node = nodes[partner];
                std::unique_lock<std::mutex> lock(node.mtx);
                node.cv.wait(lock, [&]() {
                    return node.flag.load(std::memory_order_acquire) == local_sense;
                });
            }
        }

        // Wakeup phase: walk down the tree
        for (int level = num_levels - 1; level >= 0; --level) {
            int partner = my_id ^ (1 << level);
            if (partner < num_threads) {
                nodes[partner].flag.store(!local_sense, std::memory_order_release);
                nodes[partner].cv.notify_one();
            }
        }
    }
};

// POSIX barrier (standard interface)
class PosixBarrier {
    pthread_barrier_t barrier;

public:
    explicit PosixBarrier(int n) {
        pthread_barrier_init(&barrier, nullptr, n);
    }

    ~PosixBarrier() {
        pthread_barrier_destroy(&barrier);
    }

    void wait() {
        pthread_barrier_wait(&barrier);
    }
};

// Usage example:
void worker(int id, Barrier& barrier) {
    // Do some work
    std::cout << "Thread " << id << " phase 1\n";

    barrier.wait();  // Wait for all threads

    // Continue with next phase
    std::cout << "Thread " << id << " phase 2\n";

    barrier.wait();  // Wait again

    std::cout << "Thread " << id << " done\n";
}
