### Question 22: Reader-Writer Lock Implementation

Implement a fair reader-writer lock that:
1. Prevents writer starvation
2. Allows multiple readers concurrently
3. Uses condition variables for blocking

answer:
```c
#include <mutex>
#include <condition_variable>

class FairRWLock {
    std::mutex mtx;
    std::condition_variable readers_cv;
    std::condition_variable writers_cv;

    int readers_waiting = 0;
    int readers_active = 0;
    int writers_waiting = 0;
    int writers_active = 0;

    enum class WaiterType { NONE, READER, WRITER };
    WaiterType next_waiter = WaiterType::READER;  // Alternating ticket

public:
    // Reader lock
    void lock_read() {
        std::unique_lock<std::mutex> lock(mtx);

        // Writers have priority if any are waiting
        if (writers_active > 0 || writers_waiting > 0) {
            ++readers_waiting;
            readers_cv.wait(lock, [this]() {
                return writers_active == 0 && writers_waiting == 0;
            });
            --readers_waiting;
        }

        ++readers_active;
    }

    void unlock_read() {
        std::lock_guard<std::mutex> lock(mtx);
        --readers_active;

        if (readers_active == 0 && writers_waiting > 0) {
            writers_cv.notify_one();
        }
    }

    // Writer lock
    void lock_write() {
        std::unique_lock<std::mutex> lock(mtx);
        ++writers_waiting;

        readers_cv.wait(lock, [this]() {
            return readers_active == 0 && writers_active == 0;
        });

        --writers_waiting;
        ++writers_active;
    }

    void unlock_write() {
        std::lock_guard<std::mutex> lock(mtx);
        --writers_active;

        if (writers_waiting > 0) {
            writers_cv.notify_one();
        } else {
            readers_cv.notify_all();
        }
    }
};

// Starvation-free version using tickets

class StarvationFreeRWLock {
    std::mutex mtx;
    std::condition_variable cv;

    uint64_t next_ticket = 0;
    uint64_t now_serving = 0;
    int active_readers = 0;
    int active_writer = 0;

public:
    void lock_read() {
        std::unique_lock<std::mutex> lock(mtx);
        uint64_t my_ticket = next_ticket++;

        cv.wait(lock, [this, my_ticket]() {
            return now_serving == my_ticket && active_writer == 0;
        });

        ++active_readers;
        ++now_serving;
    }

    void unlock_read() {
        std::lock_guard<std::mutex> lock(mtx);
        --active_readers;

        if (active_readers == 0) {
            cv.notify_all();
        }
    }

    void lock_write() {
        std::unique_lock<std::mutex> lock(mtx);
        uint64_t my_ticket = next_ticket++;

        cv.wait(lock, [this, my_ticket]() {
            return now_serving == my_ticket && 
                   active_readers == 0 && 
                   active_writer == 0;
        });

        ++active_writer;
        ++now_serving;
    }

    void unlock_write() {
        std::lock_guard<std::mutex> lock(mtx);
        --active_writer;
        cv.notify_all();
    }
};

// RAII wrapper
template<typename RWLock>
class RWLockGuard {
    RWLock& lock;
    bool is_writer;

public:
    RWLockGuard(RWLock& l, bool writer) : lock(l), is_writer(writer) {
        if (is_writer) lock.lock_write();
        else lock.lock_read();
    }

    ~RWLockGuard() {
        if (is_writer) lock.unlock_write();
        else lock.unlock_read();
    }
};

// Usage:
FairRWLock rwlock;

void reader() {
    RWLockGuard guard(rwlock, false);
    // Read shared data
}

void writer() {
    RWLockGuard guard(rwlock, true);
    // Write shared data
}
