    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.freq = defaultdict(OrderedDict)
        self.min_freq = 0
        self.size = 0

    def _update(self, key, value=None):
        freq, node = self.cache[key]
        if value is not None:
            node.val = value
        del self.freq[freq][key]

        if not self.freq[freq]:
            del self.freq[freq]
            if self.min_freq == freq:
                self.min_freq += 1

        self.freq[freq + 1][key] = node
        node.freq += 1
        self.cache[key] = (freq + 1, node)

    def get(self, key):
        if key not in self.cache:
            return -1
        self._update(key)
        return self.cache[key][1].val

    def put(self, key, value):
        if self.capacity == 0:
            return

        if key in self.cache:
            self._update(key, value)
            return

        if self.size == self.capacity:
            lfu_key, _ = self.freq[self.min_freq].popitem(last=False)
            del self.cache[lfu_key]
            self.size -= 1

        node = Node(key, value)
