# Version 1: Optimize for Speed
# Time Complexity: O(n) average case with hash set
# Space Complexity: O(n) for the seen set and duplicates set

def find_duplicates_fast(items):
    """
    Optimized for speed using hash-based lookup.
    Tradeoff: Uses O(n) extra space for the seen set.
    """
    seen = set()
    duplicates = []

    for item in items:
        if item in seen:
            # Check if we haven't already added this to duplicates
            # This is O(1) for set lookup
            if item not in duplicates:
                duplicates.append(item)
        else:
            seen.add(item)

    return duplicates

# Even faster - avoid the duplicates list lookup
def find_duplicates_fast_v2(items):
    """
    Further optimized: Track duplicates separately to avoid O(n) lookup in duplicates list.
    Time Complexity: O(n) average case
    Space Complexity: O(n) for seen set, O(k) for duplicates where k is unique duplicates
    """
    seen = set()
    duplicates = []
    seen_duplicates = set()  # Track what we've already added to duplicates

    for item in items:
        if item in seen:
            if item not in seen_duplicates:
                duplicates.append(item)
                seen_duplicates.add(item)
        else:
            seen.add(item)

    return duplicates


# Version 2: Optimize for Memory (when items are large objects)
# Strategy: Use object IDs or hashes instead of storing the objects themselves

def find_duplicates_memory_efficient(items):
    """
    Memory-optimized version for large objects.
    Tradeoff: 
    - Uses object id() for comparison (works for mutable objects)
    - Still needs to store seen IDs (8 bytes each typically)
    - Avoids copying or hashing large objects

    Time Complexity: O(n) average case
    Space Complexity: O(n) for seen IDs (much smaller than storing full objects)
    """
    seen_ids = set()
    duplicates = []
    seen_duplicate_ids = set()

    for item in items:
        item_id = id(item)  # Get memory address (not the hash!)

        if item_id in seen_ids:
            if item_id not in seen_duplicate_ids:
                duplicates.append(item)
                seen_duplicate_ids.add(item_id)
        else:
            seen_ids.add(item_id)

    return duplicates


def find_duplicates_memory_efficient_v2(items):
    """
    Alternative memory-efficient approach using custom hash for comparable objects.

    Use case: When objects are hashable but very large.
    Instead of storing the object in a set (which might keep a reference),
    we store a tuple of values that uniquely identify the object.

    Tradeoff: Requires objects to be hashable and you to know which 
    attributes identify uniqueness.
    """
    seen_hashes = set()
    duplicates = []
    seen_duplicate_hashes = set()

    for item in items:
        # For objects, you might use a tuple of key attributes
        # Example: item_hash = (item.name, item.id)
        try:
            item_hash = hash(item)
        except TypeError:
            # If unhashable, fall back to id-based approach
            item_hash = id(item)

        if item_hash in seen_hashes:
            if item_hash not in seen_duplicate_hashes:
                duplicates.append(item)
                seen_duplicate_hashes.add(item_hash)
        else:
            seen_hashes.add(item_hash)

