# Refactored: Strategy Pattern
class ProcessingStrategy(ABC):
    """Abstract base class for processing strategies."""

    @abstractmethod
    def process(self, data: List[Dict]) -> List[Dict]:
        pass


class FilterStrategy(ProcessingStrategy):
    """Filter only active items."""

    def process(self, data: List[Dict]) -> List[Dict]:
        return [item for item in data if item.get('active', False)]


class TransformStrategy(ProcessingStrategy):
    """Transform items by adding processed flag and doubling values."""

    def process(self, data: List[Dict]) -> List[Dict]:
        result = []
        for item in data:
            processed_item = item.copy()
            processed_item['processed'] = True
            processed_item['value'] = processed_item.get('value', 0) * 2
            result.append(processed_item)
        return result


class AggregateStrategy(ProcessingStrategy):
    """Aggregate values by category."""

    def process(self, data: List[Dict]) -> List[Dict]:
        totals: Dict[str, float] = {}
        for item in data:
            category = item.get('category', 'unknown')
            totals[category] = totals.get(category, 0) + item.get('value', 0)
        return [{'category': k, 'total': v} for k, v in totals.items()]


class SortStrategy(ProcessingStrategy):
    """Sort items by value in descending order."""

    def process(self, data: List[Dict]) -> List[Dict]:
        return sorted(data, key=lambda x: x.get('value', 0), reverse=True)


class NoOpStrategy(ProcessingStrategy):
    """No processing - return data as-is."""

    def process(self, data: List[Dict]) -> List[Dict]:
        return data


class DataProcessorRefactored:
    """
    Refactored processor using Strategy Pattern.

    Benefits:
    - Open/Closed Principle: Add new strategies without modifying existing code
    - Single Responsibility: Each strategy handles one type of processing
    - Testability: Each strategy can be tested independently
    - Runtime flexibility: Strategies can be swapped at runtime
    """

    def __init__(self, strategy: ProcessingStrategy = None):
        self._strategy = strategy or NoOpStrategy()

    @property
    def strategy(self) -> ProcessingStrategy:
        return self._strategy

    @strategy.setter
    def strategy(self, strategy: ProcessingStrategy):
        """Allow strategy to be changed at runtime."""
        self._strategy = strategy

    def process(self, data: List[Dict]) -> List[Dict]:
        return self._strategy.process(data)


# Refactored: Strategy with Configuration
class ConfigurableStrategy(ProcessingStrategy):
    """Base class for strategies that need configuration."""

    def __init__(self, **config):
        self.config = config


class FilterByThresholdStrategy(ConfigurableStrategy):
    """Filter items based on a value threshold."""

    def process(self, data: List[Dict]) -> List[Dict]:
        threshold = self.config.get('threshold', 0)
        field = self.config.get('field', 'value')
        return [item for item in data if item.get(field, 0) >= threshold]


class TransformWithMappingStrategy(ConfigurableStrategy):
    """Transform items using a field mapping."""

    def process(self, data: List[Dict]) -> List[Dict]:
        mapping = self.config.get('mapping', {})
        result = []
        for item in data:
            new_item = item.copy()
            for old_field, new_field in mapping.items():
                if old_field in new_item:
                    new_item[new_field] = new_item.pop(old_field)
            result.append(new_item)
        return result


# Refactored: Strategy Factory
class StrategyFactory:
    """Factory for creating processing strategies."""

    _strategies = {
        'filter': FilterStrategy,
        'transform': TransformStrategy,
        'aggregate': AggregateStrategy,
        'sort': SortStrategy,
        'no-op': NoOpStrategy,
    }

    @classmethod
    def register(cls, name: str, strategy_class: type):
        """Register a new strategy."""
        cls._strategies[name] = strategy_class

    @classmethod
    def create(cls, name: str, **kwargs) -> ProcessingStrategy:
        """Create a strategy by name."""
        if name not in cls._strategies:
            raise ValueError(f"Unknown strategy: {name}. Available: {list(cls._strategies.keys())}")
        return cls._strategies[name](**kwargs)


