# Refactored: State Pattern
class OrderState(ABC):
    """Abstract base class for order states."""

    @abstractmethod
    def pay(self, order: 'Order', amount: float):
        pass

    @abstractmethod
    def ship(self, order: 'Order'):
        pass

    @abstractmethod
    def deliver(self, order: 'Order'):
        pass

    @abstractmethod
    def cancel(self, order: 'Order'):
        pass

    @property
    @abstractmethod
    def name(self) -> str:
        pass


class PendingState(OrderState):
    """Order is pending payment."""

    @property
    def name(self) -> str:
        return "pending"

    def pay(self, order: 'Order', amount: float):
