class OrderRefactored:
    """
    Refactored Order using State Pattern.

    Benefits:
    - Each state encapsulates its own behavior
    - State transitions are explicit and controlled
    - Easy to add new states
    - Each state's logic is isolated and testable
    """

    def __init__(self, order_id: str):
        self.order_id = order_id
        self.state: OrderState = PendingState()

    @property
    def status(self) -> str:
        return self.state.name

    def pay(self, amount: float):
        self.state.pay(self, amount)

    def ship(self):
        self.state.ship(self)

    def deliver(self):
        self.state.deliver(self)

    def cancel(self):
        self.state.cancel(self)


# Refactored: Generic State Machine
class StateMachine:
    """
    Generic state machine implementation.
    Useful for simpler state management needs.
    """

    def __init__(self, initial_state: str):
        self._state = initial_state
        self._transitions: Dict[str, Dict[str, str]] = {}
        self._handlers: Dict[str, Dict[str, Callable]] = {}
        self._on_enter: Dict[str, Callable] = {}
        self._on_exit: Dict[str, Callable] = {}

    def add_transition(
        self, 
        from_state: str, 
        to_state: str, 
        event: str,
        handler: Optional[Callable] = None
    ):
        """Add a valid state transition."""
        if from_state not in self._transitions:
            self._transitions[from_state] = {}
        self._transitions[from_state][event] = to_state

        if handler:
            if from_state not in self._handlers:
                self._handlers[from_state] = {}
            self._handlers[from_state][event] = handler

    def add_enter_handler(self, state: str, handler: Callable):
        """Add a handler called when entering a state."""
        self._on_enter[state] = handler

    def add_exit_handler(self, state: str, handler: Callable):
        """Add a handler called when exiting a state."""
        self._on_exit[state] = handler

    @property
    def state(self) -> str:
        return self._state

    def trigger(self, event: str, *args, **kwargs) -> bool:
        """Trigger an event to transition states."""
        if self._state in self._transitions:
            if event in self._transitions[self._state]:
                # Call exit handler
                if self._state in self._on_exit:
                    self._on_exit[self._state]()

                # Transition to new state
                self._state = self._transitions[self._state][event]

                # Call handler if exists
                if self._state in self._handlers:
                    if event in self._handlers[self._state]:
                        self._handlers[self._state][event](*args, **kwargs)

                # Call enter handler
                if self._state in self._on_enter:
                    self._on_enter[self._state]()

                return True
        return False

    def can_transition(self, event: str) -> bool:
        """Check if an event can trigger a valid transition."""
        return (
            self._state in self._transitions and 
            event in self._transitions[self._state]
        )

    def get_available_events(self) -> Set[str]:
        """Get all events available from current state."""
        if self._state in self._transitions:
            return set(self._transitions[self._state].keys())
        return set()


# Refactored: Enum-based State Machine (Python 3.11+)
from enum import Enum, auto

class OrderStatus(Enum):
    PENDING = auto()
    PAID = auto()
    SHIPPED = auto()
    DELIVERED = auto()
    CANCELLED = auto()


class OrderStateMachine:
    """
    Enum-based state machine for Order.
    More concise but less flexible than State Pattern.
    """

    # Define valid transitions: {current_state: {event: new_state}}
    TRANSITIONS = {
        OrderStatus.PENDING: {'pay': OrderStatus.PAID, 'cancel': OrderStatus.CANCELLED},
        OrderStatus.PAID: {'ship': OrderStatus.SHIPPED, 'cancel': OrderStatus.CANCELLED},
        OrderStatus.SHIPPED: {'deliver': OrderStatus.DELIVERED},
        OrderStatus.DELIVERED: {},  # Terminal state
        OrderStatus.CANCELLED: {},  # Terminal state
    }

    def __init__(self, order_id: str):
        self.order_id = order_id
        self._status = OrderStatus.PENDING

    @property
    def status(self) -> OrderStatus:
        return self._status

    def pay(self, amount: float):
        self._transition('pay', amount)

    def ship(self):
        self._transition('ship')

    def deliver(self):
        self._transition('deliver')

    def cancel(self):
        self._transition('cancel')

    def _transition(self, event: str, *args):
        transitions = self.TRANSITIONS.get(self._status, {})
        if event in transitions:
            new_status = transitions[event]
            print(f"Order {self.order_id}: {self._status.name} -> {new_status.name}")
            self._status = new_status
        else:
            print(f"Cannot {event} order in {self._status.name} status")

    def can_pay(self) -> bool:
        return 'pay' in self.TRANSITIONS.get(self._status, {})

    def can_ship(self) -> bool:
        return 'ship' in self.TRANSITIONS.get(self._status, {})

    def can_cancel(self) -> bool:
        return 'cancel' in self.TRANSITIONS.get(self._status, {})


# Demonstration
if __name__ == "__main__":
    print("=== Original (Conditional Logic) ===")
    order = Order("ORD-001")
    order.pay(100)
    order.ship()
    order.deliver()

    print("\n=== Refactored (State Pattern) ===")
    order = OrderRefactored("ORD-002")
    print(f"Initial status: {order.status}")
    order.pay(100)
    order.ship()
    order.deliver()

    print("\n=== State Pattern - Cancellation Flow ===")
    order = OrderRefactored("ORD-003")
    order.pay(100)
    order.cancel()  # Should work from paid state

    print("\n=== Generic State Machine ===")
    sm = StateMachine("initial")

    sm.add_transition("initial", "active", "start")
    sm.add_transition("active", "completed", "finish")
    sm.add_transition("active", "failed", "fail")
    sm.add_transition("failed", "initial", "retry")

    sm.add_enter_handler("active", lambda: print("Entering active state"))
    sm.add_enter_handler("completed", lambda: print("Task completed!"))

    print(f"Initial state: {sm.state}")
    print(f"Available events: {sm.get_available_events()}")

    sm.trigger("start")
    print(f"After start: {sm.state}")

    sm.trigger("finish")
    print(f"After finish: {sm.state}")

    print("\n=== Enum-based State Machine ===")
    order = OrderStateMachine("ORD-004")
    print(f"Initial status: {order.status.name}")

    order.pay(100)
    print(f"Can ship: {order.can_ship()}")

    order.ship()
    order.deliver()

    print("\n=== Enum-based - Invalid Transition ===")
    order = OrderStateMachine("ORD-005")
    order.pay(100)
    order.deliver()  # Invalid - can't deliver before shipping
