import pytest

def read_config(filename):
    with open(filename, 'r') as f:
        return f.read()

def write_config(filename, content):
    with open(filename, 'w') as f:
        f.write(content)

class TestConfigFiles:
    def test_write_and_read_config(self, tmp_path):
        config_file = tmp_path / "config.txt"
        content = "database=localhost\nport=5432"

        write_config(str(config_file), content)
        result = read_config(str(config_file))

        assert result == content

    def test_read_nonexistent_file_raises_error(self, tmp_path):
        nonexistent = tmp_path / "nonexistent.txt"

        with pytest.raises(FileNotFoundError):
            read_config(str(nonexistent))

    def test_overwrite_config(self, tmp_path):
        config_file = tmp_path / "config.txt"

        write_config(str(config_file), "version=1")
        write_config(str(config_file), "version=2")

        assert read_config(str(config_file)) == "version=2"
