import pytest

class BankAccount:
    def __init__(self, initial_balance=0):
        if initial_balance < 0:
            raise ValueError("Initial balance cannot be negative")
        self.balance = initial_balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")
        self.balance += amount
        return self.balance

    def withdraw(self, amount):
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")
        if amount > self.balance:
            raise ValueError("Insufficient funds")
        self.balance -= amount
        return self.balance

    def get_balance(self):
        return self.balance

class TestBankAccount:
    def test_initial_balance_default(self):
        account = BankAccount()
        assert account.get_balance() == 0

    def test_initial_balance_positive(self):
        account = BankAccount(100)
        assert account.get_balance() == 100

    def test_initial_balance_negative_raises_error(self):
        with pytest.raises(ValueError, match="Initial balance cannot be negative"):
            BankAccount(-50)

    def test_deposit(self):
        account = BankAccount(100)
        account.deposit(50)
        assert account.get_balance() == 150

    def test_deposit_zero_raises_error(self):
        account = BankAccount()
        with pytest.raises(ValueError, match="Deposit amount must be positive"):
            account.deposit(0)

    def test_deposit_negative_raises_error(self):
        account = BankAccount()
        with pytest.raises(ValueError, match="Deposit amount must be positive"):
            account.deposit(-10)

    def test_withdraw(self):
        account = BankAccount(100)
        account.withdraw(30)
        assert account.get_balance() == 70

    def test_withdraw_insufficient_funds(self):
        account = BankAccount(50)
        with pytest.raises(ValueError, match="Insufficient funds"):
            account.withdraw(100)

    def test_withdraw_zero_raises_error(self):
        account = BankAccount()
        with pytest.raises(ValueError, match="Withdrawal amount must be positive"):
            account.withdraw(0)
