```python
"""
Write tests for a database connection context manager.

class DatabaseConnection:
    def __init__(self, connection_string):
        self.connection_string = connection_string
        self.connection = None

    def __enter__(self):
        self.connection = f"Connected to {self.connection_string}"
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.connection = None
        return False

    def execute(self, query):
        if not self.connection:
            raise RuntimeError("Not connected")
        return f"Executed: {query}"

def transaction(db, queries):
    if not db.connection:
        raise RuntimeError("Not connected")
    results = []
    for query in queries:
        results.append(db.execute(query))
    return results
"""
import pytest

class DatabaseConnection:
    def __init__(self, connection_string):
        self.connection_string = connection_string
        self.connection = None

    def __enter__(self):
        self.connection = f"Connected to {self.connection_string}"
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.connection = None
        return False

    def execute(self, query):
        if not self.connection:
            raise RuntimeError("Not connected")
        return f"Executed: {query}"

def transaction(db, queries):
    if not db.connection:
        raise RuntimeError("Not connected")
    results = []
    for query in queries:
        results.append(db.execute(query))
    return results

class TestDatabaseConnection:
    def test_context_manager_enters(self):
        with DatabaseConnection("localhost:5432") as db:
            assert db.connection == "Connected to localhost:5432"

    def test_context_manager_exits(self):
        db = DatabaseConnection("localhost:5432")
        with db:
            pass
        assert db.connection is None

    def test_execute_without_connection(self):
        db = DatabaseConnection("localhost:5432")

        with pytest.raises(RuntimeError, match="Not connected"):
            db.execute("SELECT * FROM users")

    def test_execute_with_connection(self):
        with DatabaseConnection("localhost:5432") as db:
            result = db.execute("SELECT * FROM users")
            assert result == "Executed: SELECT * FROM users"

    def test_context_manager_exception_handling(self):
        """Test that exceptions are properly propagated"""
        with pytest.raises(ValueError):
            with DatabaseConnection("localhost:5432") as db:
                raise ValueError("Test exception")

        # Connection should still be closed
        assert db.connection is None

    def test_transaction_success(self):
        with DatabaseConnection("localhost:5432") as db:
            queries = ["INSERT INTO users VALUES (1)", "INSERT INTO posts VALUES (1)"]
            results = transaction(db, queries)

            assert len(results) == 2
            assert results[0] == "Executed: INSERT INTO users VALUES (1)"
            assert results[1] == "Executed: INSERT INTO posts VALUES (1)"

    def test_transaction_without_connection(self):
        db = DatabaseConnection("localhost:5432")

        with pytest.raises(RuntimeError, match="Not connected"):
            transaction(db, ["SELECT * FROM users"])
