    def test_create_user_missing_name(self, client):
        response = client.post(
            '/api/users',
            json={},
            content_type='application/json'
        )
        data = response.get_json()

        assert response.status_code == 201
        assert data['name'] is None
```

### 20. **Testing with Monkeypatching**

```python
"""
Write tests that use monkeypatch to modify behavior at runtime.

import os
import json

def get_environment():
    return {
        'python_version': os.environ.get('PYTHON_VERSION', 'unknown'),
        'debug_mode': os.environ.get('DEBUG', 'false').lower() == 'true'
    }

def read_config():
    with open('config.json', 'r') as f:
        return json.load(f)

def get_current_time():
    from datetime import datetime
    return datetime.now().isoformat()
"""
import pytest
import json
from datetime import datetime

def get_environment():
    import os
    return {
        'python_version': os.environ.get('PYTHON_VERSION', 'unknown'),
        'debug_mode': os.environ.get('DEBUG', 'false').lower() == 'true'
    }

def read_config():
    with open('config.json', 'r') as f:
        return json.load(f)

def get_current_time():
    from datetime import datetime
    return datetime.now().isoformat()

class TestWithMonkeypatch:
    def test_get_environment_defaults(self, monkeypatch):
        # Remove environment variables if they exist
        monkeypatch.delenv('PYTHON_VERSION', raising=False)
        monkeypatch.delenv('DEBUG', raising=False)

        result = get_environment()

        assert result['python_version'] == 'unknown'
        assert result['debug_mode'] is False

    def test_get_environment_with_values(self, monkeypatch):
        monkeypatch.setenv('PYTHON_VERSION', '3.11')
        monkeypatch.setenv('DEBUG', 'true')

        result = get_environment()

        assert result['python_version'] == '3.11'
        assert result['debug_mode'] is True

    def test_read_config_with_monkeypatch(self, monkeypatch, tmp_path):
        config_file = tmp_path / "config.json"
        config_file.write_text('{"database": "testdb", "port": 5432}')

        monkeypatch.chdir(tmp_path)

        result = read_config()

        assert result['database'] == 'testdb'
        assert result['port'] == 5432

    def test_get_current_time_with_monkeypatch(self, monkeypatch):
        fixed_time = datetime(2024, 1, 15, 12, 0, 0)

        class MockDatetime:
            @classmethod
            def now(cls):
                return fixed_time

        monkeypatch.setattr('datetime', MockDatetime)

        result = get_current_time()

        assert result == '2024-01-15T12:00:00'

    def test_environment_override(self, monkeypatch):
        monkeypatch.setenv('DEBUG', 'true')

        result = get_environment()

        assert result['debug_mode'] is True

        # Now override it
        monkeypatch.setenv('DEBUG', 'false')

        result = get_environment()

        assert result['debug_mode'] is False
```

