## Custom Fixtures

### Basic Fixture Structure

```python
# conftest.py
import pytest
from typing import Generator

@pytest.fixture
def sample_data():
    """Basic fixture that returns sample data."""
    return {"name": "test", "value": 42}

@pytest.fixture
def database_connection():
    """Fixture that handles setup and teardown."""
    connection = create_connection()
    yield connection
    connection.close()

@pytest.fixture
def clean_database(database_connection):
    """Fixture that depends on another fixture."""
    database_connection.clear()
    yield database_connection
    database_connection.clear()
```

### Fixture with Teardown

```python
import pytest
import tempfile
import shutil

@pytest.fixture
def temp_directory():
    """Fixture that creates and cleans up a temporary directory."""
    temp_dir = tempfile.mkdtemp()
    yield temp_dir
    shutil.rmtree(temp_dir)

@pytest.fixture
def sample_files(temp_directory):
    """Create sample files for testing."""
    files = []
    for i in range(3):
        file_path = f"{temp_directory}/file_{i}.txt"
        with open(file_path, 'w') as f:
            f.write(f"Content {i}")
        files.append(file_path)
    return files
```

