## Fixtures with Parameters


```python
import pytest

@pytest.fixture(params=[1, 2, 3, 4])
def number_fixture(request):
    """Fixture that runs for each parameter value."""
    return request.param

def test_numbers(number_fixture):
    """Test will run 4 times with values 1, 2, 3, 4."""
    assert number_fixture > 0

# Multiple parameters with different types
@pytest.fixture(params=[
    "string_value",
    123,
    [1, 2, 3],
    {"key": "value"}
])
def mixed_type_fixture(request):
    """Test different types."""
    return request.param

def test_mixed_types(mixed_type_fixture):
    """Test will run 4 times with different types."""
    assert mixed_type_fixture is not None
```

