## Session-Scoped Fixtures

### When to Use Session Scope

```python
import pytest

@pytest.fixture(scope='session')
def browser():
    """Browser instance shared across all tests."""
    from selenium import webdriver
    driver = webdriver.Chrome()
    yield driver
    driver.quit()

@pytest.fixture(scope='session')
def api_client():
    """API client shared across all tests."""
    import requests
    client = requests.Session()
    client.headers.update({'Authorization': 'Bearer token'})
    yield client
    client.close()

@pytest.fixture(scope='session')
def test_data():
    """Load test data once for the entire session."""
    import json
    with open('tests/fixtures/test_data.json') as f:
        return json.load(f)
```

### Module vs Session Scope

```python
# conftest.py
import pytest

@pytest.fixture(scope='module')
def shared_resource():
    """Shared within a module."""
    print("\nSetting up module resource")
    resource = {'initialized': True}
    yield resource
    print("\nTearing down module resource")

@pytest.fixture(scope='session')
def session_resource():
    """Shared across entire test session."""
    print("\nSetting up session resource")
    resource = {'session': True}
    yield resource
    print("\nTearing down session resource")
```

