## Fixture Factories

### Factory Pattern for Fixtures

```python
import pytest

@pytest.fixture
def user_factory(db):
    """Factory fixture that creates user objects."""
    created_users = []

    def _create_user(name, email, **kwargs):
        user = User(name=name, email=email, **kwargs)
        db.add(user)
        db.commit()
        created_users.append(user)
        return user

    yield _create_user

    # Cleanup
    for user in created_users:
        db.delete(user)
    db.commit()

def test_create_single_user(user_factory):
    """Create one user."""
    user = user_factory("Alice", "alice@example.com")
    assert user.name == "Alice"

def test_create_multiple_users(user_factory):
    """Create multiple users."""
    users = [
        user_factory("Alice", "alice@example.com"),
        user_factory("Bob", "bob@example.com")
    ]
    assert len(users) == 2
```

### Dynamic Fixture Creation

```python
import pytest

@pytest.fixture
def file_factory(tmp_path):
    """Factory for creating test files."""
    def _create_file(name, content=""):
        file_path = tmp_path / name
        file_path.write_text(content)
        return file_path
    return _create_file

def test_file_creation(file_factory):
    """Create files using factory."""
    file1 = file_factory("test1.txt", "Hello")
    file2 = file_factory("test2.txt", "World")

    assert file1.read_text() == "Hello"
    assert file2.read_text() == "World"
