## Plugin Development

### Basic Plugin Structure

```python
# my_plugin.py
import pytest

def pytest_configure(config):
    """Called after command line options have been parsed."""
    config.addinivalue_line(
        "markers", "slow: marks tests as slow"
    )

def pytest_collection_modifyitems(config, items):
    """Modify test items during collection."""
    for item in items:
        if "integration" in item.nodeid:
            item.add_marker(pytest.mark.slow)

def pytest_report_header(config):
    """Add custom header to test report."""
    return ["Custom Header: Test Suite"]

@pytest.hookimpl(tryfirst=True)
def pytest_runtest_makereport(item, call):
    """Hook into test reporting."""
    if call.when == "call":
        # Custom reporting logic
        pass
```

### Custom Markers Plugin

```python
# markers_plugin.py
import pytest
from typing import List

class MarkerManager:
    def __init__(self):
        self.markers: List[str] = []

    def register_marker(self, name: str, description: str):
        self.markers.append(name)
        # Register with pytest
        pytest.mark.__dict__[name] = pytest.mark.__getattr__(name)

@pytest.fixture
def marker_manager():
    """Fixture to manage custom markers."""
    manager = MarkerManager()
    yield manager
    # Cleanup if needed
