## Hooks and Customization

### Test Collection Hooks

```python
# conftest.py
import pytest
import os

def pytest_collection_modifyitems(config, items):
    """Modify test items after collection."""
    # Add custom markers based on test names
    for item in items:
        if "integration" in item.nodeid:
            item.add_marker(pytest.mark.integration)
        if "unit" in item.nodeid:
            item.add_marker(pytest.mark.unit)

def pytest_collection_finish(session):
    """Called after collection is complete."""
    print(f"\nCollected {len(session.items)} tests")

def pytest_ignore_collect(collection_path, config):
    """Skip collection of certain paths."""
    if "venv" in str(collection_path):
        return True
    return False
```

### Test Execution Hooks

```python
# conftest.py
import pytest
import time

@pytest.hookimpl(tryfirst=True, hookwrapper=True)
def pytest_runtest_makereport(item, call):
    """Make test results available to other hooks."""
    outcome = yield
    report = outcome.get_result()

    # Store results for later use
    if report.when == "call":
        item.test_result = report.passed

@pytest.fixture(autouse=True)
def test_timer(request):
    """Time each test."""
    start = time.time()
    yield
    duration = time.time() - start
    print(f"\nTest duration: {duration:.2f}s")

def pytest_runtest_logreport(report):
    """Process test reports."""
    if report.failed:
        print(f"\nFAILED: {report.nodeid}")
```

### Reporting Hooks

```python
# conftest.py
import pytest

def pytest_report_header(config):
