## Advanced Mocking

### Mocking with Context Managers

```python
import pytest
from unittest.mock import patch, MagicMock
import contextlib

@pytest.fixture
def mock_database():
    """Mock database with context manager support."""
    with patch('app.database.Connection') as mock_conn:
        mock_instance = MagicMock()
        mock_conn.return_value = mock_instance
        yield mock_instance

def test_database_operations(mock_database):
    """Test with mocked database."""
    mock_database.execute.return_value = {"rows": []}

    result = app.query("SELECT * FROM users")

    assert result["rows"] == []

def test_file_operations():
    """Test file operations with mocked filesystem."""
    with patch('builtins.open', create=True) as mock_open:
        mock_file = MagicMock()
        mock_file.__enter__.return_value = mock_file
        mock_file.__exit__.return_value = False
        mock_file.read.return_value = "file content"
        mock_open.return_value = mock_file

        result = read_file("test.txt")

        assert result == "file content"
```

### Mock Chaining

```python
import pytest
from unittest.mock import MagicMock

def test_nested_mock_calls():
    """Test nested mock object access."""
    mock_obj = MagicMock()
    mock_obj.get_connection().execute().fetchall.return_value = [
        {"id": 1, "name": "Alice"}
    ]

    # Access nested attributes
    result = mock_obj.get_connection().execute().fetchall()

    assert len(result) == 1
    assert result[0]["name"] == "Alice"

def test_mock_with_spec():
    """Mock with spec to match interface."""
    from datetime import datetime

    mock_date = MagicMock(spec=datetime)

    # Only available methods/attributes
    mock_date.now.return_value = datetime(2024, 1, 1)

    result = mock_date.now()
    assert result.year == 2024
```

### Async Mocking

```python
import pytest
import asyncio
from unittest.mock import AsyncMock

@pytest.mark.asyncio
async def test_async_mock():
    """Test async functions with mocked dependencies."""
    mock_service = AsyncMock()
    mock_service.fetch_data.return_value = {"result": "success"}

    result = await mock_service.fetch_data("test_url")

    assert result["result"] == "success"

@pytest.mark.asyncio
async def test_async_context_manager():
    """Test async context managers."""
    mock_db = AsyncMock()
    mock_db.__aenter__.return_value = mock_db
    mock_db.__aexit__.return_value = None
    mock_db.query.return_value = [{"id": 1}]

    async with mock_db as db:
        result = await db.query("SELECT 1")

    assert result[0]["id"] == 1
