## Performance Testing

### Timing Tests

```python
import pytest
import time

def test_performance_sort():
    """Test that sorting 10000 items takes less than 1 second."""
    data = list(range(10000))

    start = time.time()
    result = sorted(data, reverse=True)
    duration = time.time() - start

    assert duration < 1.0
    assert result[0] == 9999

@pytest.mark.benchmark(group="sorting")
def test_benchmark_sorting(benchmark):
    """Benchmark sorting performance."""
    data = list(range(1000))
    result = benchmark(sorted, data)
    assert result[0] == 0

def test_complex_calculation(benchmark):
    """Benchmark complex calculations."""
    def calculation():
        return sum(i ** 2 for i in range(1000))

    result = benchmark(calculation)
    assert result == 333833500
```

