## Test Structure

### AAA Pattern (Arrange-Act-Assert)

```python
def test_transfer_money():
    """Test transferring money between accounts."""
    # Arrange
    source_account = BankAccount(balance=1000)
    target_account = BankAccount(balance=500)

    # Act
    source_account.transfer(target_account, 300)

    # Assert
    assert source_account.balance == 700
    assert target_account.balance == 800

def test_user_registration():
    """Test user registration flow."""
    # Arrange
    user_data = {
        "username": "testuser",
        "email": "test@example.com",
        "password": "securepassword123"
    }

    # Act
    user = UserService.register(user_data)

    # Assert
    assert user.username == "testuser"
    assert user.is_active is True
    assert user.password_hash != "securepassword123"
```

### Given-When-Then Pattern

```python
def test_withdraw_from_savings_account():
    """Test withdrawing from a savings account."""
    # Given
    account = SavingsAccount(balance=1000, interest_rate=0.02)

    # When
    account.withdraw(200)

    # Then
    assert account.balance == 800
    assert account.interest_accrued == 0

def test_api_returns_404_for_nonexistent_resource():
    """Test API returns 404 for non-existent resource."""
    # Given
    api_client = APIClient(base_url="https://api.example.com")
    nonexistent_id = "non-existent-id"

    # When
    response = api_client.get(f"/users/{nonexistent_id}")

    # Then
    assert response.status_code == 404
    assert response.json()["error"] == "User not found"
```

### One Assertion Per Test (Preferred but Flexible)

