## 7. Decision Support Agent

The Decision Support Agent helps engineering leaders make better decisions by providing structured analysis, pros/cons, and recommendations.

```python
"""
Decision Support Agent for Engineering Leaders
Provides structured decision analysis with clear recommendations
"""

import json
from typing import List, Dict, Optional, Tuple
from dataclasses import dataclass
from enum import Enum


class DecisionPriority(Enum):
    LOW = "low"
    MEDIUM = "medium"
    HIGH = "high"
    CRITICAL = "critical"


class DecisionUrgency(Enum):
    DEFERRED = "can wait"
    SOON = "within sprint"
    URGENT = "this week"
    IMMEDIATE = "now"


@dataclass
class DecisionCriteria:
    name: str
    weight: float  # 0-1, importance relative to other criteria
    options_scores: Dict[str, float]  # option -> score 0-10


@dataclass
class Decision:
    title: str
    description: str
    options: List[str]
    criteria: List[DecisionCriteria]
    constraints: List[str]
    stakeholders: List[str]
    priority: DecisionPriority
    urgency: DecisionUrgency
    deadline: Optional[str] = None


@dataclass
class DecisionAnalysis:
    decision: Decision
    recommended_option: str
    confidence: float  # 0-1
    reasoning: str
    pros_cons: Dict[str, List[str]]
    risks: List[Dict[str, str]]
    alternatives: List[str]
    implementation_notes: str


class DecisionSupportAgent:
    """Agent that helps engineering leaders make structured decisions."""

    def __init__(self, openai_api_key: str):
        self.client = OpenAI(api_key=openai_api_key)

    def create_decision(
        self,
        title: str,
        description: str,
        options: List[str],
        constraints: List[str],
        priority: str = "medium",
        urgency: str = "soon"
    ) -> Decision:
        """Create a new decision object."""
        return Decision(
            title=title,
            description=description,
            options=options,
            criteria=[],  # To be added
            constraints=constraints,
            stakeholders=[],  # To be identified
            priority=DecisionPriority(priority),
            urgency=DecisionUrgency(urgency)
        )

    def add_criteria(
        self,
        decision: Decision,
        criteria_with_weights: Dict[str, float]
    ) -> Decision:
        """Add evaluation criteria with weights."""
        decision.criteria = [
            DecisionCriteria(
                name=name,
                weight=weight,
                options_scores={opt: 0 for opt in decision.options}
            )
            for name, weight in criteria_with_weights.items()
        ]
        return decision

    def evaluate_options(
        self,
        decision: Decision,
        scores: Dict[str, Dict[str, int]]
    ) -> Decision:
        """Add scores for each option across criteria."""
        for criteria in decision.criteria:
            if criteria.name in scores:
                criteria.options_scores = scores[criteria.name]
        return decision

    def calculate_recommendation(self, decision: Decision) -> Tuple[str, float]:
        """Calculate weighted scores and return recommendation."""
        if not decision.criteria:
            return decision.options[0], 0.5  # Default to first option

        weighted_scores = {opt: 0.0 for opt in decision.options}

        for criteria in decision.criteria:
            total_weight = sum(c.weight for c in decision.criteria)
            normalized_weight = criteria.weight / total_weight

            for option, score in criteria.options_scores.items():
                weighted_scores[option] += (score / 10) * normalized_weight

        # Find best option
        best_option = max(weighted_scores, key=weighted_scores.get)
        confidence = weighted_scores[best_option]

        return best_option, confidence

    def analyze_decision(
        self,
        decision: Decision,
        pros_cons: Dict[str, Tuple[List[str], List[str]]],
        risks: List[Dict[str, str]]
    ) -> DecisionAnalysis:
        """Generate full analysis of the decision."""
        recommended, confidence = self.calculate_recommendation(decision)

        # Format pros/cons
        formatted_pros_cons = {}
        for option, (pros, cons) in pros_cons.items():
            formatted_pros_cons[option] = {
                "pros": pros,
                "cons": cons
            }

        return DecisionAnalysis(
            decision=decision,
            recommended_option=recommended,
            confidence=confidence,
            reasoning=self._generate_reasoning(decision, recommended),
            pros_cons=formatted_pros_cons,
            risks=risks,
            alternatives=self._generate_alternatives(decision),
            implementation_notes=self._generate_implementation_notes(decision)
        )

    def _generate_reasoning(self, decision: Decision, recommended: str) -> str:
        """Generate reasoning for the recommendation."""
        messages = [
            {
                "role": "system",
                "content": """You are an expert decision analyst. Generate clear, concise reasoning 
                for why a particular option was recommended. Focus on the key factors that drove the decision."""
            },
            {
                "role": "user",
