Current Options: {', '.join(decision.options)}
Constraints: {', '.join(decision.constraints)}

Be creative but practical."""
            }
        ]

        response = self.client.chat.completions.create(
            model="gpt-4o",
            messages=messages,
            temperature=0.5,
            max_tokens=400
        )

        # Parse into list (simple parsing)
        return [line.strip() for line in response.choices[0].message.content.split('\n') if line.strip()]

    def _generate_implementation_notes(self, decision: Decision) -> str:
        """Generate implementation guidance."""
        messages = [
            {
                "role": "system",
                "content": """You are an expert engineering leader. Provide practical implementation 
                guidance for executing a decision. Include timeline, resources, and key milestones."""
            },
            {
                "role": "user",
                "content": f"""Provide implementation guidance for this decision:

Decision: {decision.title}
Recommended Option: {decision.options[0]}
Priority: {decision.priority.value}
Urgency: {decision.urgency.value}

Include:
1. Key steps to implement
2. Estimated timeline
3. Required resources
4. Success metrics"""
            }
        ]

        response = self.client.chat.completions.create(
            model="gpt-4o",
            messages=messages,
            temperature=0.3,
            max_tokens=400
        )

        return response.choices[0].message.content

    def generate_decision_document(self, analysis: DecisionAnalysis) -> str:
        """Generate a formatted decision document."""
        return f"""# Decision Document: {analysis.decision.title}

## Summary
**Recommended Option:** {analysis.recommended_option}  
**Confidence:** {analysis.confidence:.0%}  
**Priority:** {analysis.decision.priority.value.upper()}  
**Urgency:** {analysis.decision.urgency.value}

## Decision Details
**Description:** {analysis.decision.description}

**Options Considered:**
{chr(10).join(f"- {opt}" for opt in analysis.decision.options)}

**Constraints:**
{chr(10).join(f"- {c}" for c in analysis.decision.constraints)}

## Recommendation & Reasoning
{analysis.reasoning}

## Pros and Cons

{self._format_pros_cons(analysis.pros_cons)}

## Risks
| Risk | Likelihood | Impact | Mitigation |
|------|------------|--------|------------|
{chr(10).join(f"| {r['risk']} | {r.get('likelihood', 'Medium')} | {r.get('impact', 'Medium')} | {r.get('mitigation', '')} |" for r in analysis.risks)}

## Alternative Approaches
{chr(10).join(f"- {alt}" for alt in analysis.alternatives)}

## Implementation Plan
{analysis.implementation_notes}

## Stakeholders
{chr(10).join(f"- {s}" for s in analysis.decision.stakeholders)}

---
*Document generated: {datetime.now().strftime('%Y-%m-%d %H:%M')}*
"""

    def _format_pros_cons(self, pros_cons: Dict) -> str:
        """Format pros and cons section."""
        result = []
        for option, details in pros_cons.items():
            result.append(f"### {option}")
            result.append("**Pros:**")
            for pro in details.get("pros", []):
                result.append(f"- {pro}")
            result.append("**Cons:**")
            for con in details.get("cons", []):
                result.append(f"- {con}")
            result.append("")
        return "\n".join(result)

    def quick_decision(
        self,
        title: str,
        options: List[str],
        criteria: Dict[str, float],
        scores: Dict[str, Dict[str, int]]
    ) -> str:
        """Quick decision analysis without full document creation."""
        decision = Decision(
            title=title,
            description="",
            options=options,
            criteria=[],
            constraints=[],
            stakeholders=[],
            priority=DecisionPriority.MEDIUM,
            urgency=DecisionUrgency.SOON
        )

        # Add criteria
        decision = self.add_criteria(decision, criteria)

        # Evaluate
        decision = self.evaluate_options(decision, scores)

        # Analyze
        recommended, confidence = self.calculate_recommendation(decision)

        return f"""**Decision:** {title}

**Recommended:** {recommended} (confidence: {confidence:.0%})

**Scores:**
{json.dumps({opt: sum(scores[c].get(opt, 0) for c in scores) / len(scores) for opt in options}, indent=2)}
"""


