# Chapter 12: Integration Patterns and Orchestration

This chapter covers how to combine multiple agents into cohesive systems that handle complex workflows, including orchestration patterns, error handling, and production deployment strategies.

## 12.1 Multi-Agent Orchestration Architecture

### Core Orchestration Patterns

```python
"""
Multi-Agent Orchestration Framework
Implements various orchestration patterns for combining agents
"""

from typing import List, Dict, Any, Optional, Callable
from dataclasses import dataclass, field
from enum import Enum
from abc import ABC, abstractmethod
import asyncio
import json
from datetime import datetime
import uuid


class OrchestrationPattern(Enum):
    SEQUENTIAL = "sequential"      # Agents run one after another
    PARALLEL = "parallel"          # Agents run concurrently
    FAN_OUT = "fan_out"            # One triggers many
    FAN_IN = "fan_in"              # Many feed into one
    PIPELINE = "pipeline"          # Output of one feeds into next
    SUPERVISOR = "supervisor"      # One oversees others
    HIERARCHICAL = "hierarchical"  # Multiple levels of control


class AgentState(Enum):
    IDLE = "idle"
    RUNNING = "running"
    WAITING = "waiting"
    COMPLETED = "completed"
    FAILED = "failed"
    CANCELLED = "cancelled"


@dataclass
class AgentTask:
    id: str
    agent_name: str
    input_data: Dict[str, Any]
    priority: int = 0
    dependencies: List[str] = field(default_factory=list)
    timeout_seconds: int = 300
    retry_count: int = 0
    max_retries: int = 3


@dataclass
class TaskResult:
    task_id: str
    agent_name: str
    success: bool
    output: Any
    error: Optional[str] = None
    execution_time_seconds: float = 0
    metadata: Dict[str, Any] = field(default_factory=dict)


@dataclass
class WorkflowState:
    workflow_id: str
    pattern: OrchestrationPattern
