    results: Dict[str, TaskResult] = field(default_factory=dict)
    status: str = "pending"
    started_at: Optional[datetime] = None
    completed_at: Optional[datetime] = None


class BaseAgent(ABC):
    """Base class for all agents in the orchestration system."""

    def __init__(self, name: str, openai_api_key: str):
        self.name = name
        self.client = OpenAI(api_key=openai_api_key)
        self.state = AgentState.IDLE
        self.metrics = {
            "tasks_completed": 0,
            "tasks_failed": 0,
            "total_execution_time": 0
        }

    @abstractmethod
    async def execute(self, input_data: Dict[str, Any]) -> Dict[str, Any]:
        """Execute the agent's main task."""
        pass

    async def run(self, task: AgentTask) -> TaskResult:
        """Run a task and return the result."""
        start_time = datetime.now()
        self.state = AgentState.RUNNING

        try:
            output = await self.execute(task.input_data)
            execution_time = (datetime.now() - start_time).total_seconds()

            self.metrics["tasks_completed"] += 1
            self.metrics["total_execution_time"] += execution_time
            self.state = AgentState.IDLE

            return TaskResult(
                task_id=task.id,
                agent_name=self.name,
                success=True,
                output=output,
                execution_time_seconds=execution_time
            )
        except Exception as e:
            execution_time = (datetime.now() - start_time).total_seconds()
            self.metrics["tasks_failed"] += 1
            self.state = AgentState.IDLE

            return TaskResult(
                task_id=task.id,
                agent_name=self.name,
                success=False,
                output=None,
                error=str(e),
                execution_time_seconds=execution_time
            )


class Orchestrator:
    """Main orchestration engine for multi-agent workflows."""

    def __init__(self):
        self.agents: Dict[str, BaseAgent] = {}
        self.workflows: Dict[str, WorkflowState] = {}
        self.event_handlers: Dict[str, List[Callable]] = {}

    def register_agent(self, agent: BaseAgent):
        """Register an agent with the orchestrator."""
        self.agents[agent.name] = agent
        print(f"Registered agent: {agent.name}")

    def create_workflow(
        self,
        pattern: OrchestrationPattern,
        tasks: List[AgentTask]
    ) -> str:
        """Create a new workflow."""
        workflow_id = str(uuid.uuid4())

        workflow = WorkflowState(
            workflow_id=workflow_id,
            pattern=pattern,
            tasks={task.id: task for task in tasks}
        )

        self.workflows[workflow_id] = workflow
        return workflow_id

    async def execute_workflow(self, workflow_id: str) -> Dict[str, Any]:
        """Execute a workflow based on its pattern."""
        workflow = self.workflows.get(workflow_id)
        if not workflow:
            raise ValueError(f"Workflow {workflow_id} not found")

        workflow.status = "running"
        workflow.started_at = datetime.now()

        try:
            if workflow.pattern == OrchestrationPattern.SEQUENTIAL:
                result = await self._execute_sequential(workflow)

