## 11. Handling Rate Limits and Retries

**Scenario:** You're building a critical data pipeline that processes thousands of records. You need to handle rate limits gracefully.

**The Problem:** When you hit rate limits, you don't want to lose data or crash. You need exponential backoff with jitter.

**Solution:**

```javascript
// Configuration
const MAX_RETRIES = 5;
const BASE_DELAY = 1000; // 1 second
const MAX_DELAY = 30000; // 30 seconds

// Exponential backoff with jitter
function calculateDelay(attempt, baseDelay = BASE_DELAY, maxDelay = MAX_DELAY) {
  // Exponential: 1s, 2s, 4s, 8s, 16s...
  const exponentialDelay = baseDelay * Math.pow(2, attempt);

  // Add jitter (Â±25%)
  const jitter = exponentialDelay * 0.25 * (Math.random() * 2 - 1);

  // Cap at max
  return Math.min(exponentialDelay + jitter, maxDelay);
}

// Check if error is retryable
function isRetryable(error) {
  if (error.status === 429) return true; // Rate limit
  if (error.status === 500) return true; // Server error
  if (error.status === 503) return true; // Service unavailable
  if (error.code === 'ECONNRESET') return true;
  if (error.code === 'ETIMEDOUT') return true;
  return false;
}

// Retry wrapper
async function withRetry(fn, options = {}) {
  const maxRetries = options.maxRetries ?? MAX_RETRIES;
  const baseDelay = options.baseDelay ?? BASE_DELAY;
  const maxDelay = options.maxDelay ?? MAX_DELAY;

  let lastError;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;

      // Don't retry on last attempt
      if (attempt === maxRetries) break;

      // Don't retry non-retryable errors
      if (!isRetryable(error)) throw error;

      // Calculate and wait
      const delay = calculateDelay(attempt, baseDelay, maxDelay);
      console.log(`Attempt ${attempt + 1} failed. Retrying in ${Math.round(delay)}ms...`);

      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }

  throw lastError;
}

// Usage with OpenAI API
async function processWithRetry(messages) {
  return withRetry(
    () => openai.chat.completions.create({
      messages,
      max_tokens: 100
    }),
    { maxRetries: 5 }
  );
}

// Batch processing with concurrency control
async function processBatch(items, processFn, options = {}) {
  const concurrency = options.concurrency ?? 5;
  const results = [];
  const errors = [];

  // Process in chunks
  for (let i = 0; i < items.length; i += concurrency) {
    const chunk = items.slice(i, i + concurrency);

    const chunkResults = await Promise.allSettled(
      chunk.map(item => withRetry(() => processFn(item)))
    );

    chunkResults.forEach((result, index) => {
      if (result.status === 'fulfilled') {
        results.push({ item, result: result.value });
      } else {
        errors.push({ item, error: result.reason });
      }
    });

    // Rate limit protection: wait between chunks
    if (i + concurrency < items.length) {
      await new Promise(r => setTimeout(r, 100));
    }
  }

  return { results, errors };
}

