**Advanced: Smart Rate Limit Handling**

```javascript
class RateLimitHandler {
  constructor() {
    this.requestsThisMinute = 0;
    this.lastReset = Date.now();
    this.minuteLimit = 500; // Adjust based on your tier
    this.retryAfter = null;
  }

  async waitIfNeeded() {
    // Check if we need to reset counter
    const now = Date.now();
    if (now - this.lastReset > 60000) {
      this.requestsThisMinute = 0;
      this.lastReset = now;
    }

    // Check explicit retry-after header
    if (this.retryAfter && Date.now() < this.retryAfter) {
      const waitTime = this.retryAfter - Date.now();
      console.log(`Waiting ${waitTime}ms for rate limit reset`);
      await new Promise(r => setTimeout(r, waitTime));
      this.retryAfter = null;
    }

    // Check if we're at limit
    if (this.requestsThisMinute >= this.minuteLimit) {
      const waitTime = 60000 - (now - this.lastReset);
      console.log(`Rate limit reached. Waiting ${waitTime}ms`);
      await new Promise(r => setTimeout(r, waitTime));
      this.requestsThisMinute = 0;
      this.lastReset = Date.now();
    }

    this.requestsThisMinute++;
  }

  handleRateLimitError(headers) {
    // Parse Retry-After header
    const retryAfter = headers['retry-after'];
    if (retryAfter) {
      this.retryAfter = Date.now() + (parseInt(retryAfter) * 1000);
    }
  }
}

const rateLimiter = new RateLimitHandler();

async function rateLimitedRequest(messages) {
  await rateLimiter.waitIfNeeded();

  try {
    const response = await openai.chat.completions.create({
      messages
    });
    return response;
  } catch (error) {
    if (error.status === 429) {
      rateLimiter.handleRateLimitError(error.headers);
      return rateLimitedRequest(messages); // Retry
    }
    throw error;
  }
}
```

**Key Takeaways:**
1. **Exponential backoff prevents thundering herd** - don't retry immediately
2. **Jitter avoids synchronized retries** - add randomness to delay
3. **Distinguish retryable vs non-retryable errors** - 400 errors won't fix themselves
4. **Track rate limit headers** - use Retry-After when available
5. **Concurrency control prevents overwhelming the API** - don't fire 100 requests at once

