        body: JSON.stringify({ messages: [...messages, userMessage] })
      });

      const reader = response.body.getReader();
      const decoder = new TextDecoder();

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value);
        const lines = chunk.split('\n');

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = JSON.parse(line.slice(6));
            if (data.content) {
              setCurrentResponse(prev => prev + data.content);
            }
          }
        }
      }
    } catch (error) {
      console.error('Error:', error);
    } finally {
      setStreaming(false);
      setMessages(prev => [...prev, { role: "assistant", content: currentResponse }]);
      setCurrentResponse("");
    }
  };

  return (
    <div>
      <div className="messages">
        {messages.map((msg, i) => (
          <div key={i} className={msg.role}>
            {msg.content}
          </div>
        ))}
        {streaming && <div className="assistant streaming">{currentResponse}</div>}
      </div>
      <input 
        value={input} 
        onChange={e => setInput(e.target.value)}
        onKeyPress={e => e.key === 'Enter' && sendMessage()}
        disabled={streaming}
      />
      <button onClick={sendMessage} disabled={streaming}>Send</button>
    </div>
  );
}
```

**Streaming with Progress Updates:**

```javascript
async function streamWithProgress(messages, onProgress) {
  const stream = await openai.chat.completions.create({
    messages,
    stream: true
  });

  let fullResponse = "";
  const startTime = Date.now();

  for await (const chunk of stream) {
    const content = chunk.choices[0]?.delta?.content;
    if (content) {
      fullResponse += content;

      // Calculate tokens per second
      const elapsed = (Date.now() - startTime) / 1000;
      const tps = fullResponse.length / elapsed;

      onProgress({
        text: fullResponse,
        tokensPerSecond: tps.toFixed(1),
        elapsed: `${elapsed.toFixed(1)}s`
      });
    }
  }

  return fullResponse;
}

// Usage
await streamWithProgress(
  [{ role: "user", content: "Explain quantum computing" }],
  ({ text, tokensPerSecond, elapsed }) => {
    updateUI({ text, tps: tokensPerSecond, elapsed });
  }
);
```

**Key Takeaways:**
1. **Streaming reduces perceived latency** - users see results immediately
2. **Use Server-Sent Events (SSE)** - standard for streaming to browsers
3. **Handle connection drops gracefully** - implement reconnection logic
4. **Track metrics** - tokens/second helps monitor performance
5. **Buffer appropriately** - don't update UI on every single character

