## 13. Context Window Management

**Scenario:** You're building a document analysis system that processes long documents. You need to manage the context window carefully.

**The Problem:** 
- Context windows are finite (e.g., 128K tokens for gpt-4o)
- Longer contexts are more expensive and slower
- Models can lose focus on distant information

**Solution:**

```javascript
// Token estimation (approximate)
function estimateTokens(text) {
  // Rough estimate: ~4 characters per token for English
  return Math.ceil(text.length / 4);
}

// Check if content fits in context
function fitsInContext(text, maxTokens = 100000, reservedTokens = 2000) {
  const estimated = estimateTokens(text);
  return estimated + reservedTokens <= maxTokens;
}

// Truncate to fit
function truncateToFit(text, maxTokens, reservedTokens = 2000) {
  const availableTokens = maxTokens - reservedTokens;
  const maxChars = availableTokens * 4;

  if (text.length <= maxChars) return text;

  return text.slice(0, maxChars) + "... [truncated]";
}

// Smart chunking for long documents
function chunkDocument(text, options = {}) {
  const {
    maxTokens = 8000, // Leave room for response
    overlap = 500,    // Token overlap between chunks
    chunkBy = 'paragraph' // 'paragraph', 'sentence', or 'character'
  } = options;

  const chunks = [];

  if (chunkBy === 'paragraph') {
    const paragraphs = text.split(/\n\n+/);
    let currentChunk = [];
    let currentTokens = 0;

    for (const para of paragraphs) {
      const paraTokens = estimateTokens(para);

      if (currentTokens + paraTokens > maxTokens && currentChunk.length > 0) {
        chunks.push(currentChunk.join('\n\n'));
        // Start new chunk with overlap
        const overlapParagraphs = [];
        let overlapTokens = 0;
        for (const p of currentChunk.reverse()) {
          const pTokens = estimateTokens(p);
          if (overlapTokens + pTokens > overlap) break;
          overlapParagraphs.unshift(p);
          overlapTokens += pTokens;
        }
        currentChunk = overlapParagraphs;
        currentTokens = overlapTokens;
      }

      currentChunk.push(para);
      currentTokens += paraTokens;
    }

    if (currentChunk.length > 0) {
      chunks.push(currentChunk.join('\n\n'));
    }
  }

  return chunks;
}

// Process long document with summary
async function analyzeLongDocument(document) {
  const maxContextTokens = 128000;
  const responseTokens = 4000;
  const availableForDocument = maxContextTokens - responseTokens - 500; // Safety margin

  // Check if document fits
  if (fitsInContext(document, maxContextTokens, responseTokens)) {
    // Document fits in one call
    return callAPI(document);
  }

  // Document too long - chunk and summarize
  console.log("Document too long, chunking...");
  const chunks = chunkDocument(document, { maxTokens: 8000 });
  console.log(`Split into ${chunks.length} chunks`);

  // Analyze each chunk
  const chunkSummaries = [];
  for (let i = 0; i < chunks.length; i++) {
    const summary = await callAPI(
      `Analyze this section and provide key points:\n\n${chunks[i]}`
    );
    chunkSummaries.push({ chunk: i + 1, summary });
  }

  // Combine summaries
  const combinedSummary = await callAPI(
    `Based on these section summaries, provide a comprehensive analysis:\n\n${
      chunkSummaries.map(s => `Section ${s.chunk}: ${s.summary}`).join('\n\n')
    }`
  );

  return combinedSummary;
}

// Sliding window for conversation history
class ConversationManager {
  constructor(maxTokens = 128000, reservedTokens = 4000) {
    this.maxTokens = maxTokens;
    this.reservedTokens = reservedTokens;
    this.messages = [];
  }

  addMessage(role, content) {
    this.messages.push({ role, content, tokens: estimateTokens(content) });
    this.trim();
  }

  trim() {
    const availableTokens = this.maxTokens - this.reservedTokens;
    let totalTokens = this.messages.reduce((sum, m) => sum + m.tokens, 0);

    // Remove oldest messages until we fit
    while (totalTokens > availableTokens && this.messages.length > 1) {
      const removed = this.messages.shift();
      totalTokens -= removed.tokens;
    }
  }

  getMessages() {
    return this.messages.map(m => ({ role: m.role, content: m.content }));
  }

  getTokenCount() {
    return this.messages.reduce((sum, m) => sum + m.tokens, 0);
  }
}

// Usage
