conversation.addMessage("system", "You are a helpful assistant.");
conversation.addMessage("user", "Hi, my name is John.");
conversation.addMessage("assistant", "Hello John! How can I help you today?");
conversation.addMessage("user", "I need help with my order #12345.");
// ... many more messages ...

const response = await openai.chat.completions.create({
  messages: conversation.getMessages(),
  max_tokens: 2000
});
