## 16. Cost Optimization Strategies

**Scenario:** You're running a production system with thousands of daily API calls. You need to reduce costs without sacrificing quality.

**The Problem:** API costs can spiral quickly. You need strategies to minimize expenses while maintaining performance.

**Solution:**

```javascript
// Strategy 1: Use the right model for the task
const modelSelection = {
  // Simple classification, tagging, extraction
  simple: "gpt-4o-mini",

  // Standard conversations, general tasks
  standard: "gpt-4o-mini",

  // Complex reasoning, nuanced tasks
  complex: "gpt-4o",

  // Code generation, technical tasks
  code: "gpt-4o"
};

// Route requests to appropriate models
function selectModel(taskType, complexity = 'medium') {
  if (taskType === 'simple' || complexity === 'low') {
    return modelSelection.simple;
  }
  if (taskType === 'complex' || complexity === 'high') {
    return modelSelection.complex;
  }
  return modelSelection.standard;
}

// Strategy 2: Optimize prompts to reduce tokens
function optimizePrompt(prompt) {
  // Remove redundant phrases
  return prompt
    .replace(/Please /g, '')
    .replace(/Could you /g, '')
    .replace(/Can you /g, '')
    .trim();
}

// Strategy 3: Cache common responses
class ResponseCache {
  constructor(maxSize = 1000) {
    this.cache = new Map();
    this.maxSize = maxSize;
  }

  generateKey(messages, model) {
    return JSON.stringify({ messages, model });
  }

  get(messages, model) {
    const key = this.generateKey(messages, model);
    return this.cache.get(key);
  }

  set(messages, model, response) {
    if (this.cache.size >= this.maxSize) {
      // Remove oldest entry
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }
    const key = this.generateKey(messages, model);
    this.cache.set(key, response);
  }

  clear() {
    this.cache.clear();
  }
}

// Strategy 4: Semantic caching for similar queries
function generateCacheKey(text) {
  // Normalize text
  return text
    .toLowerCase()
    .replace(/[^\w\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 100); // First 100 chars as key
}

class SemanticCache {
  constructor(threshold = 0.9) {
    this.cache = new Map();
    this.threshold = threshold; // Similarity threshold
  }

  // Simple hash-based key for speed
  getKey(text) {
    const normalized = text.toLowerCase().replace(/[^\w]/g, '');
    return normalized.slice(0, 50);
  }

  get(text) {
    const key = this.getKey(text);
    return this.cache.get(key);
  }

  set(text, response) {
    const key = this.getKey(text);
    this.cache.set(key, response);
  }
}

// Strategy 5: Batch similar requests
async function batchRequests(requests, options = {}) {
  const { batchSize = 20, delay = 100 } = options;
  const results = [];

  for (let i = 0; i < requests.length; i += batchSize) {
    const batch = requests.slice(i, i + batchSize);

    const batchResults = await Promise.all(
      batch.map(req => openai.chat.completions.create(req))
    );

    results.push(...batchResults);

    // Rate limit protection
    if (i + batchSize < requests.length) {
      await new Promise(r => setTimeout(r, delay));
    }
  }

  return results;
}

// Strategy 6: Use max_tokens wisely
function estimateMaxTokens(task) {
  const limits = {
    short_answer: 50,
    explanation: 200,
    detailed_analysis: 500,
    long_form: 1000,
    code_snippet: 300
  };
  return limits[task] || 200;
}

// Strategy 7: Implement fallback chain
async function callWithFallback(messages, options = {}) {
  const { preferredModel = 'gpt-4o-mini', fallbackModel = 'gpt-4o-mini' } = options;

  try {
    const response = await openai.chat.completions.create({
      messages,
      max_tokens: options.maxTokens || 200
    });
    return response;
  } catch (error) {
    if (error.status === 429 || error.status >= 500) {
      console.log(`Primary model failed, trying fallback...`);
      return openai.chat.completions.create({
        messages,
        max_tokens: options.maxTokens || 200
      });
    }
    throw error;
  }
}

// Cost tracking
class CostTracker {
  constructor() {
    this.stats = {
      totalTokens: 0,
      promptTokens: 0,
      completionTokens: 0,
      totalCost: 0,
      byModel: {}
    };
  }

  recordUsage(usage, model) {
    const pricing = {
      'gpt-4o': { prompt: 0.000005, completion: 0.000015 }, // $5/$15 per 1M tokens
      'gpt-4o-mini': { prompt: 0.00000015, completion: 0.0000006 } // $0.15/$0.60 per 1M
    };

    const rates = pricing[model] || pricing['gpt-4o-mini'];
    const cost = (usage.prompt_tokens * rates.prompt) + 
                 (usage.completion_tokens * rates.completion);

    this.stats.totalTokens += usage.total_tokens;
    this.stats.promptTokens += usage.prompt_tokens;
    this.stats.completionTokens += usage.completion_tokens;
    this.stats.totalCost += cost;

    if (!this.stats.byModel[model]) {
      this.stats.byModel[model] = { tokens: 0, cost: 0 };
    }
    this.stats.byModel[model].tokens += usage.total_tokens;
    this.stats.byModel[model].cost += cost;
  }

  getReport() {
    return {
      ...this.stats,
      averageCostPerCall: this.stats.totalCost / (this.stats.totalTokens || 1) * 1000
    };
  }
}

// Optimized API wrapper
class OptimizedAPIClient {
  constructor() {
    this.cache = new SemanticCache();
    this.costTracker = new CostTracker();
  }

  async complete(messages, options = {}) {
    const {
      model = 'gpt-4o-mini',
      taskType = 'standard',
      maxTokens,
      useCache = true
    } = options;

    // Check cache
    const lastMessage = messages[messages.length - 1].content;
    if (useCache) {
      const cached = this.cache.get(lastMessage);
      if (cached) {
        console.log('Cache hit!');
        return cached;
      }
    }

    // Estimate max tokens
    const tokens = maxTokens || estimateMaxTokens(taskType);

    // Make request
    const response = await openai.chat.completions.create({
      model,
      messages,
      max_tokens: tokens
    });

    // Track cost
    this.costTracker.recordUsage(response.usage, model);

    // Cache response
    if (useCache) {
      this.cache.set(lastMessage, response);
    }

    return response;
  }

  getCostReport() {
    return this.costTracker.getReport();
  }
}

// Usage
