## 17. Error Handling Patterns

**Scenario:** You're building a production system that needs to handle various failure modes gracefully.

**The Problem:** API calls can fail in many ways. You need robust error handling that provides good UX and debugging info.

**Solution:**

```javascript
// Custom error classes
class APIError extends Error {
  constructor(message, status, code, details = {}) {
    super(message);
    this.name = 'APIError';
    this.status = status;
    this.code = code;
    this.details = details;
  }
}

class RateLimitError extends APIError {
  constructor(retryAfter, details = {}) {
    super('Rate limit exceeded', 429, 'RATE_LIMIT', details);
    this.retryAfter = retryAfter;
  }
}

class AuthenticationError extends APIError {
  constructor(details = {}) {
    super('Authentication failed', 401, 'AUTH_ERROR', details);
  }
}

class ValidationError extends APIError {
  constructor(message, details = {}) {
    super(message, 400, 'VALIDATION_ERROR', details);
  }
}

class ContextLengthError extends APIError {
  constructor(maxTokens, details = {}) {
    super('Context length exceeded', 400, 'CONTEXT_LENGTH', details);
    this.maxTokens = maxTokens;
  }
}

// Error handler with retry logic
async function handleAPIError(error, context = {}) {
  const { operation, attempt = 1, maxAttempts = 3 } = context;

  // Log error details
  console.error('API Error:', {
    message: error.message,
    status: error.status,
    code: error.code,
    attempt,
    operation
  });

  // Handle specific error types
  if (error instanceof RateLimitError) {
    console.log(`Rate limited. Waiting ${error.retryAfter}s...`);
    await new Promise(r => setTimeout(r, error.retryAfter * 1000));
    return { shouldRetry: true, delay: error.retryAfter * 1000 };
  }

  if (error instanceof AuthenticationError) {
    // Don't retry auth errors - they won't fix themselves
    return { shouldRetry: false, fatal: true };
  }

  if (error instanceof ValidationError) {
    // Don't retry validation errors - fix the input
    return { shouldRetry: false, fatal: false };
  }

  if (error instanceof ContextLengthError) {
    // Reduce context and retry
    return { shouldRetry: true, reduceContext: true };
  }

  // Network errors - retry with backoff
  if (!error.status || error.status >= 500) {
    if (attempt < maxAttempts) {
      const delay = Math.pow(2, attempt) * 1000; // 2s, 4s, 8s
      return { shouldRetry: true, delay };
    }
  }

  return { shouldRetry: false, fatal: false };
}

// Robust API wrapper
class RobustAPIClient {
  constructor(options = {}) {
    this.maxRetries = options.maxRetries || 3;
    this.onError = options.onError || console.error;
  }

  async complete(messages, options = {}) {
    let lastError;
    let context = { operation: 'complete' };

    for (let attempt = 1; attempt <= this.maxRetries; attempt++) {
      context.attempt = attempt;

      try {
        return await this.executeRequest(messages, options);
      } catch (error) {
        lastError = error;

        // Wrap raw errors
        const wrappedError = this.wrapError(error);
        context.wrappedError = wrappedError;

        // Handle the error
        const handling = await handleAPIError(wrappedError, context);

        if (handling.fatal) {
          throw wrappedError;
        }

        if (!handling.shouldRetry) {
          throw wrappedError;
        }

        // Wait before retry
        if (handling.delay) {
          await new Promise(r => setTimeout(r, handling.delay));
        }

        // Reduce context if needed
        if (handling.reduceContext && messages.length > 2) {
          messages = this.reduceContext(messages);
        }
      }
    }

    throw lastError;
  }

  wrapError(error) {
    if (error.status === 429) {
      const retryAfter = error.headers?.['retry-after'] || 60;
      return new RateLimitError(parseInt(retryAfter), { original: error });
    }
    if (error.status === 401) {
      return new AuthenticationError({ original: error });
    }
    if (error.status === 400 && error.message.includes('maximum context length')) {
      return new ContextLengthError(128000, { original: error });
    }
    if (error.status === 400) {
      return new ValidationError(error.message, { original: error });
    }
    return new APIError(
      error.message || 'Unknown error',
      error.status || 0,
      error.code || 'UNKNOWN',
      { original: error }
    );
  }

  reduceContext(messages) {
    // Keep system message and last few messages
    const systemMsg = messages.find(m => m.role === 'system');
    const recentMsgs = messages.slice(-4); // Last 4 messages

    if (systemMsg) {
      return [systemMsg, ...recentMsgs];
    }
    return recentMsgs;
  }

  async executeRequest(messages, options) {
    try {
      const response = await openai.chat.completions.create({
        messages,
        max_tokens: options.maxTokens || 500,
        temperature: options.temperature
      });
      return response;
    } catch (error) {
      // Add status code if missing
      if (!error.status && error.message) {
        error.status = error.message.includes('timeout') ? 408 : 500;
      }
      throw error;
    }
  }
}

// Usage with proper error handling
async function main() {
  const client = new RobustAPIClient({
    maxRetries: 3,
    onError: (error) => {
      // Send to error tracking service
      console.error('Error:', error);
    }
  });

  try {
    const response = await client.complete(
      [{ role: "user", content: "Hello!" }],
    );
    console.log("Success:", response.choices[0].message.content);
  } catch (error) {
    if (error instanceof RateLimitError) {
      console.log("Rate limited. Try again later.");
    } else if (error instanceof AuthenticationError) {
      console.log("Check your API key.");
    } else if (error instanceof ContextLengthError) {
      console.log("Reduce your input size.");
    } else {
      console.log("Unexpected error:", error.message);
    }
  }
}

// Validation helper
function validateMessages(messages) {
  if (!Array.isArray(messages)) {
    throw new ValidationError('messages must be an array');
  }

  if (messages.length === 0) {
    throw new ValidationError('messages cannot be empty');
  }

  for (const msg of messages) {
    if (!msg.role || !['system', 'user', 'assistant'].includes(msg.role)) {
      throw new ValidationError(`Invalid role: ${msg.role}`);
    }
    if (!msg.content || typeof msg.content !== 'string') {
      throw new ValidationError('message content must be a string');
    }
  }

  return true;
}
```

**Key Takeaways:**
1. **Create custom error types** - makes handling specific errors easier
2. **Implement retry logic** - transient failures often succeed on retry
3. **Distinguish fatal vs retryable errors** - don't retry what won't fix
4. **Log comprehensively** - you need details for debugging
5. **Provide context** - include operation name, attempt number, etc.

