class MetricsCollector {
  constructor() {
    this.metrics = {
      requests: 0,
      successes: 0,
      failures: 0,
      totalLatency: 0,
      tokenUsage: { prompt: 0, completion: 0, total: 0 },
      errors: {},
      byModel: {}
    };
  }

  recordRequest(params, result) {
    this.metrics.requests++;

    if (result.error) {
      this.metrics.failures++;
      this.metrics.errors[result.error.code] = 
        (this.metrics.errors[result.error.code] || 0) + 1;
    } else {
      this.metrics.successes++;
      this.metrics.totalLatency += result.latency;

      if (result.usage) {
        this.metrics.tokenUsage.prompt += result.usage.prompt_tokens;
        this.metrics.tokenUsage.completion += result.usage.completion_tokens;
        this.metrics.tokenUsage.total += result.usage.total_tokens;
      }

      const model = params.model || 'gpt-4o-mini';
      if (!this.metrics.byModel[model]) {
        this.metrics.byModel[model] = { requests: 0, tokens: 0 };
      }
      this.metrics.byModel[model].requests++;
      this.metrics.byModel[model].tokens += result.usage?.total_tokens || 0;
    }
  }

