      averageLatency: this.metrics.successes > 0
        ? (this.metrics.totalLatency / this.metrics.successes).toFixed(0) + 'ms'
        : '0ms'
    };
  }

  reset() {
    this.metrics = {
      requests: 0,
      successes: 0,
      failures: 0,
      totalLatency: 0,
      tokenUsage: { prompt: 0, completion: 0, total: 0 },
      errors: {},
      byModel: {}
    };
