// Simple conversation manager
class ConversationManager {
  constructor(systemPrompt = "", maxHistory = 10) {
    this.messages = [];
    this.maxHistory = maxHistory;

    if (systemPrompt) {
      this.messages.push({ role: "system", content: systemPrompt });
    }
  }

  addUserMessage(content) {
    this.messages.push({ role: "user", content });
  }

  addAssistantMessage(content) {
    this.messages.push({ role: "assistant", content });
  }

  async send() {
    const response = await openai.chat.completions.create({
      messages: this.messages,
      max_tokens: 1000
    });

    const assistantMessage = response.choices[0].message.content;
    this.addAssistantMessage(assistantMessage);

    // Trim old messages if exceeding max
    if (this.messages.length > this.maxHistory + 1) {
      // Keep system message + last N messages
      const systemMsg = this.messages[0];
      const recentMsgs = this.messages.slice(-this.maxHistory);
      this.messages = [systemMsg, ...recentMsgs];
    }

    return assistantMessage;
  }

