        "To handle authentication",
      ],
      correctAnswer: 1,
    },
    {
      id: 8,
      question: "Which HTTP method is typically used to update a resource partially?",
      options: ["PUT", "PATCH", "POST", "DELETE"],
      correctAnswer: 1,
    },
    {
      id: 9,
      question: "What is eventual consistency?",
      options: [
        "Data is always immediately consistent across all nodes",
        "Data will become consistent over time after writes",
        "Data is never consistent",
        "Data consistency is guaranteed by transactions",
      ],
      correctAnswer: 1,
    },
    {
      id: 10,
      question: "What is the main benefit of using a message queue in system design?",
      options: [
        "Faster database queries",
        "Decoupling producers and consumers with async communication",
        "Simplifying API design",
        "Reducing server costs",
      ],
      correctAnswer: 1,
    },
  ];

  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [score, setScore] = useState(0);
  const [quizComplete, setQuizComplete] = useState(false);

  const handleAnswerSelect = (index: number) => {
    if (selectedAnswer !== null) return;
    setSelectedAnswer(index);
    setShowExplanation(true);
    if (index === questions[currentQuestion].correctAnswer) {
      setScore(score + 1);
    }
  };

  const handleNext = () => {
    if (currentQuestion < questions.length - 1) {
      setCurrentQuestion(currentQuestion + 1);
      setSelectedAnswer(null);
      setShowExplanation(false);
    } else {
      setQuizComplete(true);
    }
  };

  const resetQuiz = () => {
    setCurrentQuestion(0);
    setSelectedAnswer(null);
    setShowExplanation(false);
    setScore(0);
    setQuizComplete(false);
  };

  if (quizComplete) {
    return (
      <div className="space-y-6">
        <Card className="p-8 text-center">
          <h2 className="text-2xl font-bold mb-4">Quiz Complete!</h2>
          <p className="text-4xl font-bold text-primary mb-2">
            {score} / {questions.length}
          </p>
          <p className="text-muted-foreground mb-6">
            {score === questions.length
              ? "Perfect score! Excellent understanding of system design!"
              : score >= questions.length * 0.7
              ? "Great job! You have a solid understanding."
              : "Keep learning! Review the concepts and try again."}
          </p>
          <Button onClick={resetQuiz}>Try Again</Button>
        </Card>
      </div>
    );
  }

  const question = questions[currentQuestion];

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-xl font-semibold">System Design Quiz</h2>
        <span className="text-sm text-muted-foreground">
          Question {currentQuestion + 1} of {questions.length}
        </span>
      </div>

      <Progress value={(currentQuestion / questions.length) * 100} />

      <Card className="p-6">
        <p className="text-lg mb-6">{question.question}</p>

        <div className="space-y-3">
          {question.options.map((option, index) => (
            <button
              key={index}
              onClick={() => handleAnswerSelect(index)}
              disabled={selectedAnswer !== null}
              className={`w-full p-4 text-left rounded-lg border transition-all ${
                selectedAnswer === null
                  ? "border-border hover:border-primary hover:bg-accent"
                  : selectedAnswer === index
                  ? index === question.correctAnswer
                    ? "border-green-500 bg-green-500/10"
                    : "border-red-500 bg-red-500/10"
                  : index === question.correctAnswer
                  ? "border-green-500 bg-green-500/10"
                  : "border-border opacity-50"
              }`}
            >
              <span className="font-medium">{String.fromCharCode(65 + index)}.</span> {option}
            </button>
          ))}
        </div>

        {showExplanation && (
          <div className="mt-6 p-4 bg-accent rounded-lg">
            <p className="font-medium mb-2">
              {selectedAnswer === question.correctAnswer ? (
                <span className="text-green-600">â Correct!</span>
              ) : (
                <span className="text-red-600">â Incorrect</span>
              )}
            </p>
            <p className="text-sm text-muted-foreground">
              {explanations[question.id] || "Explanation not available."}
            </p>
          </div>
        )}
      </Card>

      {selectedAnswer !== null && (
        <div className="flex justify-end">
          <Button onClick={handleNext}>
            {currentQuestion < questions.length - 1 ? "Next Question" : "See Results"}
          </Button>
        </div>
      )}
    </div>
  );
}
