                  onClick={() => setSelectedComponent(comp.id)}
                >
                  <div className="text-2xl mb-1">{componentIcons[comp.type]}</div>
                  <div className="font-medium text-sm">{comp.name}</div>
                  <div className="text-xs text-muted-foreground capitalize">{comp.type}</div>
                </div>
              ))}
            </div>

            {selectedComponent && (
              <div className="mt-4 flex gap-2">
                <Button
                  variant="destructive"
                  size="sm"
                  onClick={() => deleteComponent(selectedComponent)}
                >
                  Delete Selected
                </Button>
                <Button size="sm" variant="outline" onClick={() => setSelectedComponent(null)}>
                  Deselect
                </Button>
              </div>
            )}
          </Card>
        </TabsContent>

        <TabsContent value="components" className="mt-4">
          <Card className="p-4 space-y-4">
            <div className="flex gap-2">
              <Input
                placeholder="Component name"
                value={newComponentName}
                onChange={(e) => setNewComponentName(e.target.value)}
              />
              <select
                className="flex h-10 rounded-md border border-input bg-background px-3 py-2"
                value={newComponentType}
                onChange={(e) => setNewComponentType(e.target.value as Component["type"])}
              >
                <option value="client">Client</option>
                <option value="server">Server</option>
                <option value="database">Database</option>
                <option value="cache">Cache</option>
                <option value="queue">Queue</option>
                <option value="cdn">CDN</option>
                <option value="gateway">Gateway</option>
              </select>
              <Button onClick={addComponent}>Add Component</Button>
            </div>

            <div className="space-y-2">
              {components.map((comp) => (
                <div
                  key={comp.id}
                  className="flex items-center justify-between p-3 bg-accent rounded-lg"
                >
                  <div className="flex items-center gap-3">
                    <span className="text-2xl">{componentIcons[comp.type]}</span>
                    <div>
                      <div className="font-medium">{comp.name}</div>
                      <div className="text-sm text-muted-foreground capitalize">
                        {comp.type}
                      </div>
                    </div>
                  </div>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => deleteComponent(comp.id)}
                  >
                    Remove
                  </Button>
                </div>
              ))}
            </div>
          </Card>
        </TabsContent>

        <TabsContent value="connections" className="mt-4">
          <Card className="p-4">
            <p className="text-sm text-muted-foreground mb-4">
              Connections are automatically created based on the architecture pattern.
            </p>
            <div className="space-y-2">
              {connections.map((conn, i) => (
                <div
                  key={i}
                  className="flex items-center justify-between p-3 bg-accent rounded-lg"
                >
                  <div className="flex items-center gap-2">
                    <span className="font-medium">
                      {components.find((c) => c.id === conn.from)?.name}
                    </span>
                    <span className="text-muted-foreground">â</span>
                    <span className="font-medium">
                      {components.find((c) => c.id === conn.to)?.name}
                    </span>
                  </div>
                  {conn.label && (
                    <Badge variant="outline">{conn.label}</Badge>
                  )}
                </div>
              ))}
            </div>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}
